	cb.Allow()
	cb.RecordFailure()

	// Transition to half-open
	time.Sleep(60 * time.Millisecond)
	cb.Allow()

	// Fail in half-open
	cb.RecordFailure()

	if cb.State() != StateOpen {
		t.Errorf("expected StateOpen after failure in half-open, got %v", cb.State())
	}
}

func TestHalfOpenMaxCalls(t *testing.T) {
	cfg := BreakerConfig{
		FailureThreshold: 1,
		RecoveryTimeout:  50 * time.Millisecond,
		SuccessThreshold: 2,
		HalfOpenMaxCalls: 2,
	}
	cb := NewCircuitBreakerWithConfig(cfg)

	// Open circuit
	cb.Allow()
	cb.RecordFailure()

	// Transition to half-open
	time.Sleep(60 * time.Millisecond)
	err1 := cb.Allow()
	if err1 != nil {
		t.Errorf("first half-open request should be allowed, got %v", err1)
	}

	// Second request should be allowed
	err2 := cb.Allow()
	if err2 != nil {
		t.Errorf("second half-open request should be allowed (HalfOpenMaxCalls=2), got %v", err2)
	}

	// Third request should be rejected
	err3 := cb.Allow()
	if err3 != ErrCircuitOpen {
		t.Errorf("third half-open request should be rejected, got %v", err3)
	}
}

func TestMetrics(t *testing.T) {
	cb := NewCircuitBreaker()

	// Record some activity
	for i := 0; i < 3; i++ {
		cb.Allow()
	}

	stats := cb.Stats()
	allowed := stats["total_allowed"].(uint64)
	if allowed != 3 {
		t.Errorf("expected total_allowed=3, got %d", allowed)
	}

	// Reject due to circuit open
	cb.Allow()
	cb.RecordFailure()
	cb.Allow()
	cb.RecordFailure()
	cb.Allow()
	cb.RecordFailure()
	cb.Allow()
	cb.RecordFailure()
	cb.Allow()
	cb.RecordFailure()

	cb.Allow() // This should be rejected (circuit open)

	stats = cb.Stats()
	rejected := stats["total_rejected"].(uint64)
	if rejected < 1 {
		t.Errorf("expected total_rejected >= 1, got %d", rejected)
	}
}

func TestReset(t *testing.T) {
	cfg := BreakerConfig{
		FailureThreshold: 1,
		RecoveryTimeout:  10 * time.Millisecond,
		SuccessThreshold: 1,
		HalfOpenMaxCalls: 1,
	}
	cb := NewCircuitBreakerWithConfig(cfg)

	// Open circuit
	cb.Allow()
	cb.RecordFailure()

	if cb.State() != StateOpen {
		t.Fatal("circuit not opened")
	}

	// Reset
	cb.Reset()

	if cb.State() != StateClosed {
		t.Errorf("expected StateClosed after reset, got %v", cb.State())
	}

	stats := cb.Stats()
	if stats["total_allowed"].(uint64) != 0 {
		t.Errorf("expected total_allowed=0 after reset")
	}
}

func TestStateString(t *testing.T) {
	tests := []struct {
		state State
		want  string
	}{
		{StateClosed, "CLOSED"},
		{StateOpen, "OPEN"},
		{StateHalfOpen, "HALF_OPEN"},
		{State(99), "UNKNOWN"},
	}

	for _, tt := range tests {
		if got := tt.state.String(); got != tt.want {
			t.Errorf("State(%d).String() = %q, want %q", tt.state, got, tt.want)
		}
	}
}

func TestConcurrentAllowAndRecord(t *testing.T) {
	cb := NewCircuitBreaker()

	// Simulate concurrent requests and failures
	done := make(chan bool, 10)

	for i := 0; i < 5; i++ {
		go func() {
			defer func() { done <- true }()
			for j := 0; j < 10; j++ {
				if cb.Allow() == nil {
					cb.RecordSuccess()
				}
			}
		}()
	}

	for i := 0; i < 5; i++ {
		go func() {
			defer func() { done <- true }()
			for j := 0; j < 3; j++ {
				cb.Allow()
				cb.RecordFailure()
			}
		}()
	}

	// Wait for all goroutines
	for i := 0; i < 10; i++ {
		<-done
	}

	// Should eventually open
	if cb.State() != StateOpen {
		t.Logf("state=%v (may not be open due to timing)", cb.State())
	}
}

package dispatcher

import (
	"context"
	"fmt"
	"os/exec"
	"runtime"
	"sync"
	"sync/atomic"
	"time"

	"grie-engine/internal/shm"
)

// Worker represents a single Julia worker goroutine
type Worker struct {
	ID            int
	WorkerState   *WorkerState
	juliaProcess  *exec.Cmd
	shmPath       string
	processedJobs uint64 // atomic
	errors        uint64 // atomic
	lastError     atomic.Value // error
	cpuCore       int // CPU core to pin to (0 = no pinning)
}

// NewWorker creates a new worker for a Julia instance
func NewWorker(id int, workerState *WorkerState, cpuCore int) *Worker {
	w := &Worker{
		ID:          id,
		WorkerState: workerState,
		cpuCore:     cpuCore,
	}
	return w
}

// Start initializes the shared memory and launches the Julia process
func (w *Worker) Start(ctx context.Context) error {
	// Create shared memory for this worker
	shmMgr, err := shm.Create(10 * 1024 * 1024) // 10MB per worker
	if err != nil {
		return fmt.Errorf("failed to create shared memory: %w", err)
	}

	w.WorkerState.SHM = shmMgr
	w.shmPath = shmMgr.Path()

	// TODO: Launch Julia process
	// juliaScript := fmt.Sprintf("julia_worker_%d.jl", w.ID)
	// w.juliaProcess = exec.CommandContext(ctx, "julia", juliaScript, w.shmPath)

	return nil
}

// Run executes the worker main loop (pinned to OS thread if cpuCore >= 0)
func (w *Worker) Run(ctx context.Context, jobQueue chan *Job) error {
	// Pin to OS thread if requested
	if w.cpuCore >= 0 {
		runtime.LockOSThread()
		defer runtime.UnlockOSThread()

		// TODO: Actually pin to CPU core using taskset
		// cmd := exec.Command("taskset", "-p", "-c", fmt.Sprintf("%d", w.cpuCore), fmt.Sprintf("%d", os.Getpid()))
		// cmd.Run()
	}

	for {
		select {
		case job := <-jobQueue:
			if job == nil {
				// Channel closed
				return nil
			}

			result, err := w.processJob(ctx, job)
			if err != nil {
				atomic.AddUint64(&w.errors, 1)
				w.lastError.Store(err)
				job.Response <- nil
			} else {
				job.Response <- result
			}

			w.WorkerState.IncrementProcessed()

		case <-ctx.Done():
			return ctx.Err()
		}
	}
}

// processJob sends job to Julia via shared memory and waits for result
func (w *Worker) processJob(ctx context.Context, job *Job) ([]byte, error) {
	if w.WorkerState.SHM == nil {
		return nil, fmt.Errorf("shared memory not initialized")
	}

	// Write job payload to shared memory
	if err := w.WorkerState.SHM.WriteData(job.Payload); err != nil {
		return nil, fmt.Errorf("failed to write to shared memory: %w", err)
	}

	// Wait for Julia to process and respond
	// Using polling with timeout
	deadline := time.Now().Add(5 * time.Second)

	for {
		select {
		case <-ctx.Done():
			return nil, ctx.Err()

		default:
			if time.Now().After(deadline) {
				return nil, fmt.Errorf("timeout waiting for Julia response")
			}

			// Try to read result
			result, err := w.WorkerState.SHM.ReadData(100) // 100ms timeout per try
			if err == nil {
				return result, nil
			}

			// Not ready yet, keep polling
			time.Sleep(10 * time.Millisecond)
		}
	}
}

// GetStats returns worker statistics
func (w *Worker) GetStats() map[string]interface{} {
	lastErr := w.lastError.Load()
	errStr := ""
	if lastErr != nil {
		errStr = lastErr.(error).Error()
	}

	return map[string]interface{}{
		"id":               w.ID,
		"state":            w.WorkerState.state.Load(),
		"processed_jobs":   atomic.LoadUint64(&w.processedJobs),
		"errors":           atomic.LoadUint64(&w.errors),
		"last_error":       errStr,
		"last_seen":        w.WorkerState.GetLastSeen(),
		"shm_path":         w.shmPath,
		"cpu_core":         w.cpuCore,
	}
}

// Close cleans up the worker
func (w *Worker) Close() error {
	if w.WorkerState.SHM != nil {
		if err := w.WorkerState.SHM.Close(); err != nil {
			return fmt.Errorf("failed to close shared memory: %w", err)
		}
	}

	if w.juliaProcess != nil {
		if err := w.juliaProcess.Process.Kill(); err != nil {
			return fmt.Errorf("failed to kill Julia process: %w", err)
		}
	}

	return nil
}

// WorkerPool manages multiple workers
type WorkerPool struct {
	workers      []*Worker
	jobQueues    []chan *Job
	dispatcher   *Dispatcher
	ctx          context.Context
	cancel       context.CancelFunc
	wg           sync.WaitGroup
	totalStarted uint64 // atomic
	totalStopped uint64 // atomic
}

// NewWorkerPool creates a new worker pool
func NewWorkerPool(dispatcher *Dispatcher, workerCount int) (*WorkerPool, error) {
	workers := make([]*Worker, workerCount)
	jobQueues := make([]chan *Job, workerCount)

	for i := 0; i < workerCount; i++ {
		jobQueues[i] = make(chan *Job, 100) // Buffered job queue per worker
		workers[i] = NewWorker(i, dispatcher.workers[i], i%8) // Pin to 8 cores
	}

	ctx, cancel := context.WithCancel(context.Background())

	return &WorkerPool{
		workers:    workers,
		jobQueues:  jobQueues,
		dispatcher: dispatcher,
		ctx:        ctx,
		cancel:     cancel,
	}, nil
}

// Start launches all workers
func (wp *WorkerPool) Start(ctx context.Context) error {
	for i, worker := range wp.workers {
		if err := worker.Start(ctx); err != nil {
			return fmt.Errorf("failed to start worker %d: %w", i, err)
		}

		wp.wg.Add(1)
		go func(w *Worker, idx int) {
			defer wp.wg.Done()
			atomic.AddUint64(&wp.totalStarted, 1)

			if err := w.Run(ctx, wp.jobQueues[idx]); err != nil {
				w.lastError.Store(err)
			}

			atomic.AddUint64(&wp.totalStopped, 1)
		}(worker, i)
	}

	return nil
}

// Submit sends a job to a specific worker
func (wp *WorkerPool) Submit(workerIdx int, job *Job) error {
	if workerIdx < 0 || workerIdx >= len(wp.jobQueues) {
		return fmt.Errorf("invalid worker index: %d", workerIdx)
	}

	select {
	case wp.jobQueues[workerIdx] <- job:
		return nil
	case <-wp.ctx.Done():
		return fmt.Errorf("worker pool shutting down")
	default:
		return fmt.Errorf("worker queue full")
	}
}

// Stop gracefully shuts down all workers
func (wp *WorkerPool) Stop() error {
	wp.cancel()

	// Close all job queues
	for _, q := range wp.jobQueues {
		close(q)
	}

	// Wait for all workers to finish
	wp.wg.Wait()

	// Close all workers
	for _, w := range wp.workers {
		if err := w.Close(); err != nil {
			return err
		}
	}

	return nil
}

// Stats returns stats for all workers
func (wp *WorkerPool) Stats() []map[string]interface{} {
	stats := make([]map[string]interface{}, len(wp.workers))
	for i, w := range wp.workers {
		stats[i] = w.GetStats()
	}
	return stats
}

