package dispatcher

import (
	"context"
	"fmt"
	"os/exec"
	"runtime"
	"sync"
	"sync/atomic"
	"time"

	"grie-engine/internal/circuitbreaker"
	"grie-engine/internal/config"
	"grie-engine/internal/retry"
	"grie-engine/internal/shm"
)

// Worker represents a single Julia worker goroutine
type Worker struct {
	ID            int
	WorkerState   *WorkerState
	juliaProcess  *exec.Cmd
	shmPath       string
	processedJobs uint64 // atomic
	errors        uint64 // atomic
	lastError     atomic.Value // error
	cpuCore       int // CPU core to pin to (0 = no pinning)

	// Phase 3: Operational Excellence
	timeoutCfg     *config.TimeoutConfig
	circuitBreaker *circuitbreaker.CircuitBreaker
	retryConfig    retry.RetryConfig
}

// NewWorker creates a new worker for a Julia instance
func NewWorker(id int, workerState *WorkerState, cpuCore int) *Worker {
	w := &Worker{
		ID:             id,
		WorkerState:    workerState,
		cpuCore:        cpuCore,
		timeoutCfg:     config.DefaultTimeoutConfig(),
		circuitBreaker: circuitbreaker.NewCircuitBreaker(),
		retryConfig:    retry.DefaultRetryConfig(),
	}
	return w
}

// Start initializes the shared memory and launches the Julia process
func (w *Worker) Start(ctx context.Context) error {
	// Create shared memory for this worker
	shmMgr, err := shm.Create(10 * 1024 * 1024) // 10MB per worker
	if err != nil {
		return fmt.Errorf("failed to create shared memory: %w", err)
	}

	w.WorkerState.SHM = shmMgr
	w.shmPath = shmMgr.Path()

	// TODO: Launch Julia process
	// juliaScript := fmt.Sprintf("julia_worker_%d.jl", w.ID)
	// w.juliaProcess = exec.CommandContext(ctx, "julia", juliaScript, w.shmPath)

	return nil
}

// Run executes the worker main loop (pinned to OS thread if cpuCore >= 0)
func (w *Worker) Run(ctx context.Context, jobQueue chan *Job) error {
	// Pin to OS thread if requested
	if w.cpuCore >= 0 {
		runtime.LockOSThread()
		defer runtime.UnlockOSThread()

		// TODO: Actually pin to CPU core using taskset
		// cmd := exec.Command("taskset", "-p", "-c", fmt.Sprintf("%d", w.cpuCore), fmt.Sprintf("%d", os.Getpid()))
		// cmd.Run()
	}

	for {
		select {
		case job := <-jobQueue:
			if job == nil {
				// Channel closed
				return nil
			}

			result, err := w.processJob(ctx, job)
			if err != nil {
				atomic.AddUint64(&w.errors, 1)
				w.lastError.Store(err)
				job.Response <- nil
			} else {
				job.Response <- result
			}

			w.WorkerState.IncrementProcessed()

		case <-ctx.Done():
			return ctx.Err()
		}
	}
}

// processJob sends job to Julia via shared memory and waits for result
// Includes circuit breaker pattern, retry logic, and configurable timeouts
func (w *Worker) processJob(ctx context.Context, job *Job) ([]byte, error) {
	// Check circuit breaker first
	if err := w.circuitBreaker.Allow(); err != nil {
		return nil, &retry.RetryableError{Err: err, Type: retry.ErrorPermanent}
	}

	// Execute with retry logic
	var result []byte
	err := retry.Do(ctx, w.retryConfig, func() error {
		innerErr := w.doProcessJob(ctx)
		if innerErr != nil {
			w.circuitBreaker.RecordFailure()
			return innerErr
		}

		// Read result after successful write
		result, readErr := w.readJobResult(ctx)
		if readErr != nil {
			w.circuitBreaker.RecordFailure()
			return readErr
		}

		w.circuitBreaker.RecordSuccess()
		return nil
	})

	return result, err
}

// doProcessJob writes job to shared memory
func (w *Worker) doProcessJob(ctx context.Context) error {
	if w.WorkerState.SHM == nil {
		return fmt.Errorf("shared memory not initialized")
	}

	// Create context with timeout for SHM write
	writeCtx, cancel := context.WithTimeout(ctx, w.timeoutCfg.SHMWriteTimeout)
	defer cancel()

	// Write job payload to shared memory
	done := make(chan error, 1)
	go func() {
		done <- w.WorkerState.SHM.WriteData(w.WorkerState.Payload)
	}()

	select {
	case err := <-done:
		if err != nil {
			return &retry.RetryableError{Err: fmt.Errorf("failed to write to shared memory: %w", err), Type: retry.ErrorTransient}
		}
		return nil
	case <-writeCtx.Done():
		return &retry.RetryableError{Err: fmt.Errorf("SHM write timeout"), Type: retry.ErrorTransient}
	}
}

// readJobResult polls shared memory for job result with timeout
func (w *Worker) readJobResult(ctx context.Context) ([]byte, error) {
	deadline := time.Now().Add(w.timeoutCfg.JobProcessTimeout)

	for {
		select {
		case <-ctx.Done():
			return nil, ctx.Err()

		default:
			if time.Now().After(deadline) {
				return nil, &retry.RetryableError{Err: fmt.Errorf("timeout waiting for Julia response"), Type: retry.ErrorTransient}
			}

			// Try to read result
			result, err := w.WorkerState.SHM.ReadData(int(w.timeoutCfg.SHMReadTimeout.Milliseconds()))
			if err == nil {
				return result, nil
			}

			// Not ready yet, keep polling
			time.Sleep(10 * time.Millisecond)
		}
	}
}

// GetStats returns worker statistics
func (w *Worker) GetStats() map[string]interface{} {
	lastErr := w.lastError.Load()
	errStr := ""
	if lastErr != nil {
		errStr = lastErr.(error).Error()
	}

	return map[string]interface{}{
		"id":               w.ID,
		"state":            w.WorkerState.state.Load(),
		"processed_jobs":   atomic.LoadUint64(&w.processedJobs),
		"errors":           atomic.LoadUint64(&w.errors),
		"last_error":       errStr,
		"last_seen":        w.WorkerState.GetLastSeen(),
		"shm_path":         w.shmPath,
		"cpu_core":         w.cpuCore,
	}
}

// Close cleans up the worker
func (w *Worker) Close() error {
	if w.WorkerState.SHM != nil {
		if err := w.WorkerState.SHM.Close(); err != nil {
			return fmt.Errorf("failed to close shared memory: %w", err)
		}
	}

	if w.juliaProcess != nil {
		if err := w.juliaProcess.Process.Kill(); err != nil {
			return fmt.Errorf("failed to kill Julia process: %w", err)
		}
	}

	return nil
}

// WorkerPool manages multiple workers
type WorkerPool struct {
	workers      []*Worker
	jobQueues    []chan *Job
	dispatcher   *Dispatcher
	ctx          context.Context
	cancel       context.CancelFunc
	wg           sync.WaitGroup
	totalStarted uint64 // atomic
	totalStopped uint64 // atomic
}

// NewWorkerPool creates a new worker pool
func NewWorkerPool(dispatcher *Dispatcher, workerCount int) (*WorkerPool, error) {
	workers := make([]*Worker, workerCount)
	jobQueues := make([]chan *Job, workerCount)

	for i := 0; i < workerCount; i++ {
		jobQueues[i] = make(chan *Job, 100) // Buffered job queue per worker
		workers[i] = NewWorker(i, dispatcher.workers[i], i%8) // Pin to 8 cores
	}

	ctx, cancel := context.WithCancel(context.Background())

	return &WorkerPool{
		workers:    workers,
		jobQueues:  jobQueues,
		dispatcher: dispatcher,
		ctx:        ctx,
		cancel:     cancel,
	}, nil
}

// Start launches all workers
func (wp *WorkerPool) Start(ctx context.Context) error {
	for i, worker := range wp.workers {
		if err := worker.Start(ctx); err != nil {
			return fmt.Errorf("failed to start worker %d: %w", i, err)
		}

		wp.wg.Add(1)
		go func(w *Worker, idx int) {
			defer wp.wg.Done()
			atomic.AddUint64(&wp.totalStarted, 1)

			if err := w.Run(ctx, wp.jobQueues[idx]); err != nil {
				w.lastError.Store(err)
			}

			atomic.AddUint64(&wp.totalStopped, 1)
		}(worker, i)
	}

	return nil
}

// Submit sends a job to a specific worker
func (wp *WorkerPool) Submit(workerIdx int, job *Job) error {
	if workerIdx < 0 || workerIdx >= len(wp.jobQueues) {
		return fmt.Errorf("invalid worker index: %d", workerIdx)
	}

	select {
	case wp.jobQueues[workerIdx] <- job:
		return nil
	case <-wp.ctx.Done():
		return fmt.Errorf("worker pool shutting down")
	default:
		return fmt.Errorf("worker queue full")
	}
}

// Stop gracefully shuts down all workers
func (wp *WorkerPool) Stop() error {
	wp.cancel()

	// Close all job queues
	for _, q := range wp.jobQueues {
		close(q)
	}

	// Wait for all workers to finish
	wp.wg.Wait()

	// Close all workers
	for _, w := range wp.workers {
		if err := w.Close(); err != nil {
			return err
		}
	}

	return nil
}

// Stats returns stats for all workers
func (wp *WorkerPool) Stats() []map[string]interface{} {
	stats := make([]map[string]interface{}, len(wp.workers))
	for i, w := range wp.workers {
		stats[i] = w.GetStats()
	}
	return stats
}

package dispatcher

import (
	"context"
	"fmt"
	"sync/atomic"
	"time"

	"grie-engine/internal/shm"
)

// WorkerState tracks the state of a Julia worker
type WorkerState struct {
	ID        int
	PID       int
	SHM       *shm.SharedMemManager
	state     atomic.Value // string: IDLE, BUSY, ERROR
	lastSeen  int64        // atomic: Unix nano
	processed uint64       // atomic: count
}

// IsIdle checks if worker is ready to accept jobs
func (w *WorkerState) IsIdle() bool {
	s := w.state.Load()
	if s == nil {
		return true
	}
	return s.(string) == "IDLE"
}

// SetState updates worker state atomically
func (w *WorkerState) SetState(s string) {
	w.state.Store(s)
}

// UpdateLastSeen updates the last activity timestamp
func (w *WorkerState) UpdateLastSeen() {
	atomic.StoreInt64(&w.lastSeen, time.Now().UnixNano())
}

// GetLastSeen gets the last activity timestamp
func (w *WorkerState) GetLastSeen() time.Time {
	nano := atomic.LoadInt64(&w.lastSeen)
	return time.Unix(0, nano)
}

// IncrementProcessed increments the job counter
func (w *WorkerState) IncrementProcessed() uint64 {
	return atomic.AddUint64(&w.processed, 1)
}

// Dispatcher: 메인 오케스트레이터
// 데이터를 받아 가용한 워커에게 라운드-로빈으로 배분
type Dispatcher struct {
	workers       []*WorkerState
	ringBuffer    *RingBuffer
	roundRobin    uint64 // atomic: 다음 워커 인덱스
	jobIDCounter  uint64 // atomic: 작업 ID
	totalReceived uint64 // atomic: 수신한 작업 수
	totalDropped  uint64 // atomic: 버린 작업 수

	// Backpressure
	backpressure atomic.Value // bool
	maxQueueLen  int
}

// NewDispatcher creates a new dispatcher with N workers
func NewDispatcher(workerCount int, ringBufferCapacity uint64) (*Dispatcher, error) {
	rb, err := NewRingBuffer(ringBufferCapacity)
	if err != nil {
		return nil, fmt.Errorf("failed to create ring buffer: %w", err)
	}

	workers := make([]*WorkerState, workerCount)
	for i := 0; i < workerCount; i++ {
		workers[i] = &WorkerState{
			ID: i,
		}
		workers[i].SetState("IDLE")
	}

	d := &Dispatcher{
		workers:      workers,
		ringBuffer:   rb,
		roundRobin:   0,
		jobIDCounter: 0,
		maxQueueLen:  int(float64(ringBufferCapacity) * 0.8), // 80% of capacity
	}

	d.backpressure.Store(false)

	return d, nil
}

// Submit submits a new job to the dispatcher
// Returns job ID if successful, -1 if dropped due to backpressure
func (d *Dispatcher) Submit(payload []byte, priority int) (uint64, error) {
	// Check backpressure
	if d.IsBackpressured() {
		atomic.AddUint64(&d.totalDropped, 1)
		return ^uint64(0), fmt.Errorf("backpressure active - job dropped")
	}

	// Create job
	jobID := atomic.AddUint64(&d.jobIDCounter, 1)
	job := Job{
		ID:       jobID,
		Priority: priority,
		Payload:  payload,
		Response: make(chan []byte, 1), // Buffered to avoid blocking
	}

	// Try to publish to ring buffer
	if !d.ringBuffer.Publish(job) {
		atomic.AddUint64(&d.totalDropped, 1)
		return ^uint64(0), fmt.Errorf("ring buffer full - job dropped")
	}

	atomic.AddUint64(&d.totalReceived, 1)

	// Update backpressure flag
	queueSize := d.ringBuffer.Size()
	if queueSize > uint64(d.maxQueueLen) {
		d.backpressure.Store(true)
	}

	return jobID, nil
}

// Run starts the dispatcher (runs until context is cancelled)
// This distributes jobs from ring buffer to workers
func (d *Dispatcher) Run(ctx context.Context) error {
	for {
		select {
		case <-ctx.Done():
			return ctx.Err()

		default:
			// Try to distribute jobs
			job, ok := d.ringBuffer.Subscribe()
			if !ok {
				// No jobs available, sleep briefly
				time.Sleep(100 * time.Microsecond)
				continue
			}

			// Find next available worker (round-robin)
			workerIdx := d.findNextWorker()
			if workerIdx < 0 {
				// All workers busy, push back to ring buffer? (advanced feature)
				continue
			}

			// Assign job to worker
			worker := d.workers[workerIdx]
			worker.SetState("BUSY")
			worker.UpdateLastSeen()

			// Send to worker via channel (non-blocking)
			go d.assignJobToWorker(ctx, worker, job)

			// Update backpressure
			if d.ringBuffer.Size() < uint64(d.maxQueueLen) {
				d.backpressure.Store(false)
			}
		}
	}
}

// findNextWorker finds the next idle worker using round-robin
// Returns -1 if no idle worker found
func (d *Dispatcher) findNextWorker() int {
	start := atomic.AddUint64(&d.roundRobin, 1)
	workerCount := uint64(len(d.workers))

	for i := uint64(0); i < workerCount; i++ {
		idx := (start + i) % workerCount
		if d.workers[idx].IsIdle() {
			return int(idx)
		}
	}

	return -1 // All workers busy
}

// assignJobToWorker assigns a job to a specific worker
// This runs in a separate goroutine to avoid blocking the dispatcher
func (d *Dispatcher) assignJobToWorker(ctx context.Context, worker *WorkerState, job *Job) {
	// TODO: In real implementation, communicate with Julia via shared memory
	// For now, simulate processing
	defer func() {
		worker.SetState("IDLE")
		worker.IncrementProcessed()
	}()

	// Simulate work
	time.Sleep(10 * time.Millisecond)

	// Send dummy response
	select {
	case job.Response <- []byte("processed"):
	case <-ctx.Done():
	}
}

// IsBackpressured checks if backpressure is active
func (d *Dispatcher) IsBackpressured() bool {
	val := d.backpressure.Load()
	if val == nil {
		return false
	}
	if b, ok := val.(bool); ok {
		return b
	}
	return false
}

// Stats returns dispatcher statistics
func (d *Dispatcher) Stats() map[string]interface{} {
	idleCount := 0
	busyCount := 0
	for _, w := range d.workers {
		if w.IsIdle() {
			idleCount++
		} else {
			busyCount++
		}
	}

	return map[string]interface{}{
		"total_workers":   len(d.workers),
		"idle_workers":    idleCount,
		"busy_workers":    busyCount,
		"queue_size":      d.ringBuffer.Size(),
		"queue_capacity":  d.ringBuffer.Capacity(),
		"total_received":  atomic.LoadUint64(&d.totalReceived),
		"total_dropped":   atomic.LoadUint64(&d.totalDropped),
		"backpressured":   d.IsBackpressured(),
		"round_robin":     atomic.LoadUint64(&d.roundRobin),
	}
}

// Close gracefully shuts down the dispatcher
func (d *Dispatcher) Close() error {
	// Wait for workers to finish
	for _, w := range d.workers {
		w.SetState("SHUTDOWN")
	}
	return nil
}

