// Close gracefully shuts down the dispatcher
// Waits up to ShutdownTimeout for in-flight jobs to complete
func (d *Dispatcher) Close() error {
	var retErr error

	d.shutdownOnce.Do(func() {
		// Signal shutdown
		close(d.shutdownChan)

		// Mark all workers as shutdown
		for _, w := range d.workers {
			w.SetState("SHUTDOWN")
		}

		// Wait for in-flight jobs with timeout
		done := make(chan struct{})
		go func() {
			d.wg.Wait()
			close(done)
		}()

		select {
		case <-done:
			// All jobs completed
			return
		case <-time.After(d.timeoutCfg.ShutdownTimeout):
			retErr = fmt.Errorf("graceful shutdown timeout: jobs still in-flight after %v", d.timeoutCfg.ShutdownTimeout)
		}
	})

	return retErr
}

