	for _, m := range metrics {
		fmt.Fprintf(w, "%s %v\n", m.name, m.value)
	}

	return nil
}

// StatsJSON returns metrics in JSON-compatible format
func (r *Registry) StatsJSON() map[string]interface{} {
	return map[string]interface{}{
