/**
 * FreeLang v5 Blockchain — 공통 타입 정의
 *
 * 구성:
 *   Transaction  — 발신자/수신자/금액/서명
 *   Block        — 블록 헤더 + 트랜잭션 목록
 *   UTXO         — 미사용 출력
 *   WalletInfo   — 지갑 공개 정보
 *   MineResult   — 채굴 결과
 */

// ============================================================
// Transaction
// ============================================================

export interface Transaction {
  id:        string;       // SHA-256 해시
  from:      string;       // 발신자 주소 (공개키 해시)
  to:        string;       // 수신자 주소
  amount:    number;       // 전송량
  fee:       number;       // 수수료
  timestamp: number;       // Unix ms
  signature: string;       // ECDSA 서명 (hex)
  nonce:     number;       // 재전송 방지
}

// 코인베이스 트랜잭션 (채굴 보상)
export interface CoinbaseTx {
  id:        string;
  to:        string;
  amount:    number;
  height:    number;
  timestamp: number;
}

// ============================================================
// Block
// ============================================================

export interface BlockHeader {
  index:        number;
  previousHash: string;
  merkleRoot:   string;   // 트랜잭션 Merkle 루트
  timestamp:    number;
  difficulty:   number;
  nonce:        number;
}

export interface Block {
