     1→/**
     2→ * FreeLang v5 Blockchain — Blockchain
     3→ *
     4→ * 기능:
     5→ *   addBlock(block)          — 블록 추가 (검증 후)
     6→ *   getBalance(address)      — UTXO 기반 잔고
     7→ *   getUtxos(address)        — 미사용 출력 목록
     8→ *   getTxHistory(address)    — 트랜잭션 내역
     9→ *   isValid()                — 전체 체인 유효성
    10→ *   fork(index)              — 특정 높이에서 포크
    11→ *   getStats()               — 체인 통계
    12→ *   adjustDifficulty()       — 난이도 동적 조정 (2016블록마다)
    13→ */
    14→
    15→import { Block, Transaction, UTXO, ChainStats } from "./types";
    16→import { validateBlock } from "./block";
    17→import { createGenesisBlock } from "./block";
    18→
    19→// 목표 블록 생성 시간 (ms) — Bitcoin: 10분, 여기선 5초
    20→const TARGET_BLOCK_TIME_MS = 5_000;
    21→// 난이도 조정 주기
    22→const DIFFICULTY_ADJUST_INTERVAL = 10;
    23→// 최초 난이도
    24→const INITIAL_DIFFICULTY = 1;
    25→// 블록 보상
    26→const BLOCK_REWARD = 50;
    27→
    28→// ============================================================
    29→// UTXO Set (미사용 출력 관리)
    30→// ============================================================
    31→
    32→class UtxoSet {
    33→  private utxos: Map<string, UTXO> = new Map(); // key: txId:index
    34→
    35→  private key(txId: string, index: number): string {
    36→    return `${txId}:${index}`;
    37→  }
    38→
    39→  addOutput(txId: string, index: number, address: string, amount: number): void {
    40→    const k = this.key(txId, index);
    41→    this.utxos.set(k, { txId, index, address, amount, spent: false });
    42→  }
    43→
    44→  spend(txId: string, index: number): boolean {
    45→    const k    = this.key(txId, index);
    46→    const utxo = this.utxos.get(k);
    47→    if (!utxo || utxo.spent) return false;
    48→    utxo.spent = true;
    49→    return true;
    50→  }
    51→
    52→  getByAddress(address: string): UTXO[] {
    53→    return [...this.utxos.values()].filter(
    54→      (u) => u.address === address && !u.spent
    55→    );
    56→  }
    57→
    58→  getBalance(address: string): number {
    59→    return this.getByAddress(address).reduce((s, u) => s + u.amount, 0);
    60→  }
    61→
    62→  size(): number { return this.utxos.size; }
    63→
    64→  clone(): UtxoSet {
    65→    const copy = new UtxoSet();
    66→    for (const [k, u] of this.utxos) {
    67→      copy.utxos.set(k, { ...u });
    68→    }
    69→    return copy;
    70→  }
    71→}
    72→
    73→// ============================================================
    74→// Blockchain
    75→// ============================================================
    76→
    77→export class Blockchain {
    78→  private chain:   Block[]  = [];
    79→  private utxoSet: UtxoSet  = new UtxoSet();
    80→  private txIndex: Map<string, { blockIdx: number; tx: Transaction }> = new Map();
    81→  private difficulty: number = INITIAL_DIFFICULTY;
    82→
    83→  constructor() {
    84→    const genesis = createGenesisBlock();
    85→    this.chain.push(genesis);
    86→  }
    87→
    88→  // ── 블록 추가 ────────────────────────────────────────────
    89→
    90→  addBlock(block: Block): { ok: boolean; errors: string[] } {
    91→    const prevBlock = this.chain[this.chain.length - 1];
    92→    const result    = validateBlock(block, prevBlock, this.difficulty);
    93→
    94→    if (!result.valid) {
    95→      return { ok: false, errors: result.errors };
    96→    }
    97→
    98→    // UTXO 업데이트
    99→    this.applyBlock(block);
   100→    this.chain.push(block);
   101→
   102→    // 난이도 조정
   103→    if (this.chain.length % DIFFICULTY_ADJUST_INTERVAL === 0) {
   104→      this.adjustDifficulty();
   105→    }
   106→
   107→    return { ok: true, errors: [] };
   108→  }
   109→
   110→  /** 유효성 검사 없이 강제 추가 (테스트용) */
   111→  addBlockForce(block: Block): void {
   112→    this.applyBlock(block);
   113→    this.chain.push(block);
   114→  }
   115→
   116→  // ── UTXO 적용 ───────────────────────────────────────────
   117→
   118→  private applyBlock(block: Block): void {
