/**
 * FreeLang v5 Blockchain — Mempool (미처리 트랜잭션 풀)
 *
 * 기능:
 *   add(tx)         — 트랜잭션 추가 (중복/수수료 검증)
 *   remove(txId)    — 제거
 *   selectForBlock(maxCount) — 수수료 우선 선택
 *   clear()         — 전체 제거
 *   expire(ageMs)   — 오래된 트랜잭션 만료
 *   getStats()      — 통계
 */

import { Transaction, MempoolStats } from "./types";

// ============================================================
// Mempool
// ============================================================

export class Mempool {
  private pool:     Map<string, Transaction> = new Map();
  private minFee:   number;
  private maxSize:  number;

  constructor(options: { minFee?: number; maxSize?: number } = {}) {
    this.minFee  = options.minFee  ?? 0;
    this.maxSize = options.maxSize ?? 10_000;
  }

  // ── 추가 ────────────────────────────────────────────────

  add(tx: Transaction): { ok: boolean; reason?: string } {
    if (this.pool.has(tx.id)) {
      return { ok: false, reason: "duplicate" };
    }
    if (this.pool.size >= this.maxSize) {
      return { ok: false, reason: "mempool full" };
    }
    if (tx.fee < this.minFee) {
      return { ok: false, reason: `fee(${tx.fee}) < minFee(${this.minFee})` };
    }
    if (tx.amount <= 0) {
      return { ok: false, reason: "amount must be > 0" };
    }

    this.pool.set(tx.id, tx);
    return { ok: true };
  }

  // ── 제거 ────────────────────────────────────────────────

  remove(txId: string): boolean {
    return this.pool.delete(txId);
  }

  removeAll(txIds: string[]): void {
    for (const id of txIds) this.pool.delete(id);
  }

  clear(): void {
    this.pool.clear();
  }

  // ── 블록 선택 ────────────────────────────────────────────

  /**
   * 블록 포함 트랜잭션 선택
   * 수수료 내림차순으로 maxCount개 선택
   */
  selectForBlock(maxCount = 100): Transaction[] {
    return [...this.pool.values()]
      .sort((a, b) => b.fee - a.fee)
      .slice(0, maxCount);
  }

  // ── 만료 ────────────────────────────────────────────────

  /** ageMs(ms)보다 오래된 트랜잭션 제거 */
  expire(ageMs = 3_600_000): number {
    const cutoff = Date.now() - ageMs;
    let removed  = 0;
    for (const [id, tx] of this.pool) {
      if (tx.timestamp < cutoff) {
        this.pool.delete(id);
        removed++;
      }
    }
    return removed;
  }

  // ── 조회 ────────────────────────────────────────────────

  has(txId: string): boolean { return this.pool.has(txId); }
  get(txId: string): Transaction | undefined { return this.pool.get(txId); }
  size(): number { return this.pool.size; }

  getAll(): Transaction[] {
    return [...this.pool.values()];
  }

  getStats(): MempoolStats {
    const txs = [...this.pool.values()];
    if (txs.length === 0) {
      return { count: 0, totalFees: 0, maxFee: 0, minFee: 0 };
    }
    const fees = txs.map((t) => t.fee);
    return {
      count:     txs.length,
      totalFees: fees.reduce((a, b) => a + b, 0),
      maxFee:    Math.max(...fees),
      minFee:    Math.min(...fees),
    };
  }

  // ── 주소별 조회 ──────────────────────────────────────────

  getByAddress(address: string): Transaction[] {
    return [...this.pool.values()].filter(
      (tx) => tx.from === address || tx.to === address
    );
  }

  /** 보낸 사람 기준 nonce 확인 (replay 방지) */
  getNonce(address: string): number {
    const txs = [...this.pool.values()]
      .filter((tx) => tx.from === address)
      .map((tx) => tx.nonce);
    return txs.length > 0 ? Math.max(...txs) + 1 : 0;
  }
}

