  test("T25: mineBlock — 코인베이스 포함 Merkle Root 검증", () => {
    const genesis  = createGenesisBlock();
    const coinbase = createCoinbaseTx("miner", 50, 1);
    const result   = mineBlock(1, genesis.hash, [], coinbase, "miner", 1, 1_000_000);
    const valid    = validateBlock(result.block, genesis, 1);
