toolUseResult.originalFile:
/**
 * FreeLang v5 Blockchain — Block
 *
 * 구조:
 *   BlockHeader: index / previousHash / merkleRoot / timestamp / difficulty / nonce
 *   Block:       header + hash + transactions + coinbase + miner
 *
 * Proof-of-Work:
 *   difficulty = N → 해시 앞 N자리가 "0"이어야 함
 *   mineBlock(template, difficulty) → MineResult
 *
 * 유효성:
 *   validateBlock(block, prevBlock) → errors[]
 *   calcBlockHash(header)           → hex
 */

import { sha256d } from "./crypto-utils";
import { MerkleTree } from "./merkle-tree";
import type { Block, BlockHeader, Transaction, CoinbaseTx, MineResult, BlockValidationResult } from "./types";

// ============================================================
// 해시 계산
// ============================================================

export function calcBlockHash(header: BlockHeader): string {
  const data = JSON.stringify({
    index:        header.index,
    previousHash: header.previousHash,
    merkleRoot:   header.merkleRoot,
    timestamp:    header.timestamp,
    difficulty:   header.difficulty,
    nonce:        header.nonce,
  });
  return sha256d(data);
}

// ============================================================
// Merkle Root 계산
// ============================================================

export function calcMerkleRoot(
  transactions: Transaction[],
  coinbase:     CoinbaseTx | null
): string {
  const ids: string[] = [];
  if (coinbase) ids.push(coinbase.id);
  ids.push(...transactions.map((tx) => tx.id));
  return MerkleTree.buildRoot(ids);
}

// ============================================================
// 제네시스 블록
// ============================================================

export function createGenesisBlock(miner = "genesis"): Block {
  const header: BlockHeader = {
    index:        0,
    previousHash: "0".repeat(64),
    merkleRoot:   "0".repeat(64),
    timestamp:    0,
    difficulty:   1,
    nonce:        0,
  };

  const hash = calcBlockHash(header);

  return {
    header,
    hash,
    transactions: [],
    coinbase:     null,
    miner,
  };
}

// ============================================================
// Proof-of-Work 채굴
// ============================================================

export function mineBlock(
  index:        number,
  previousHash: string,
  transactions: Transaction[],
  coinbase:     CoinbaseTx | null,
  miner:        string,
  difficulty:   number,
  maxAttempts   = 10_000_000
): MineResult {
  const target     = "0".repeat(difficulty);
  const merkleRoot = calcMerkleRoot(transactions, coinbase);
  const timestamp  = Date.now();
  const startTime  = Date.now();

  let nonce    = 0;
  let hash     = "";
  let attempts = 0;

  const baseHeader: Omit<BlockHeader, "nonce"> = {
    index,
    previousHash,
    merkleRoot,
    timestamp,
    difficulty,
  };

  while (attempts < maxAttempts) {
    const header: BlockHeader = { ...baseHeader, nonce };
    hash = calcBlockHash(header);
    attempts++;

    if (hash.startsWith(target)) {
      const timeMs   = Date.now() - startTime || 1;
      const hashRate = Math.round((attempts / timeMs) * 1000);

      const block: Block = {
        header: { ...baseHeader, nonce },
        hash,
        transactions,
        coinbase,
        miner,
      };

      return { block, nonce, attempts, timeMs, hashRate };
    }

    nonce++;
  }

  // maxAttempts 초과 → 마지막 해시로 반환 (테스트용 폴백)
  const header: BlockHeader = { ...baseHeader, nonce };
  hash = calcBlockHash(header);
  const timeMs   = Date.now() - startTime || 1;
  const hashRate = Math.round((attempts / timeMs) * 1000);

  const block: Block = {
    header: { ...baseHeader, nonce },
    hash,
    transactions,
    coinbase,
    miner,
  };

  return { block, nonce, attempts, timeMs, hashRate };
}

// ============================================================
// 블록 유효성 검증
// ============================================================

export interface BlockValidationResult {
  valid:  boolean;
  errors: string[];
}

export function validateBlock(
  block:     Block,
  prevBlock: Block | null,
  difficulty: number
): BlockValidationResult {
  const errors: string[] = [];

  // 1. 해시 재계산
  const expectedHash = calcBlockHash(block.header);
  if (expectedHash !== block.hash) {
    errors.push(`해시 불일치: ${block.hash.slice(0, 8)}... ≠ ${expectedHash.slice(0, 8)}...`);
  }

  // 2. PoW 검증
  const target = "0".repeat(difficulty);
  if (!block.hash.startsWith(target)) {
    errors.push(`PoW 미충족: difficulty=${difficulty}`);
  }

  // 3. 이전 블록 연결
  if (prevBlock) {
    if (block.header.previousHash !== prevBlock.hash) {
      errors.push("previousHash 불일치");
    }
    if (block.header.index !== prevBlock.header.index + 1) {
      errors.push(`index 불연속: ${block.header.index} vs ${prevBlock.header.index + 1}`);
    }
  } else if (block.header.index !== 0) {
    errors.push("제네시스 블록만 prevBlock 없이 가능");
  }

  // 4. Merkle Root 검증
  const expectedRoot = calcMerkleRoot(block.transactions, block.coinbase);
  if (expectedRoot !== block.header.merkleRoot) {
    errors.push("Merkle Root 불일치");
  }

  // 5. 타임스탬프 기본 검증 (미래 2분 이내)
  if (block.header.timestamp > Date.now() + 120_000) {
    errors.push("블록 타임스탬프가 너무 미래임");
  }

  return { valid: errors.length === 0, errors };
}

// ============================================================
// Block 클래스 (Phase 1: API 일관성 강화)
// ============================================================

/**
 * Block 클래스 — 메서드 기반 API
 *
 * 마이그레이션 전략:
 *  - 기존 함수는 호환성을 위해 유지 (Deprecation 경고)
 *  - 새로운 코드는 Block.* 메서드 사용
 *  - 6개월 후 기존 함수 제거 예정
 */
export class Block {
  /**
   * 제네시스 블록 생성
   * @param miner 채굴자 주소
   * @returns 제네시스 블록
   *
   * @example
   * const genesis = Block.genesis("genesis");
   */
  static genesis(miner = "genesis"): Block {
    return createGenesisBlock(miner);
  }

  /**
   * 블록 채굴 (Proof-of-Work)
   * @param index 블록 인덱스
   * @param previousHash 이전 블록 해시
   * @param transactions 트랜잭션 목록
   * @param coinbase 코인베이스 트랜잭션
   * @param miner 채굴자 주소
   * @param difficulty 난이도
   * @param maxAttempts 최대 시도 횟수
   * @returns 채굴 결과
   *
   * @example
   * const result = Block.mine(1, prevHash, txList, coinbase, "miner1", 2);
   */
  static mine(
    index:        number,
    previousHash: string,
    transactions: Transaction[],
    coinbase:     CoinbaseTx | null,
    miner:        string,
    difficulty:   number,
    maxAttempts   = 10_000_000
  ): MineResult {
    return mineBlock(index, previousHash, transactions, coinbase, miner, difficulty, maxAttempts);
  }

  /**
   * 블록 유효성 검증
   * @param block 검증할 블록
   * @param prevBlock 이전 블록 (제네시스 블록이 아닌 경우)
   * @param difficulty 난이도
   * @returns 검증 결과
   *
   * @example
   * const result = Block.validate(block, prevBlock, 2);
   * if (!result.valid) console.error(result.errors);
   */
  static validate(
    block:     Block,
    prevBlock: Block | null,
    difficulty: number
  ): BlockValidationResult {
    return validateBlock(block, prevBlock, difficulty);
  }

  /**
   * 블록 헤더의 해시 계산
   * @param header 블록 헤더
   * @returns 계산된 해시 (hex)
   *
   * @example
   * const hash = Block.calculateHash(header);
   */
  static calculateHash(header: BlockHeader): string {
    return calcBlockHash(header);
  }
}

/**
 * FreeLang v5 Blockchain — Transaction
 *
 * 기능:
 *   TransactionBuilder  — 트랜잭션 생성/서명
 *   validateTx(tx)      — 기본 유효성 검증
 *   calcTxId(tx)        — 결정론적 ID 계산
 *   serializeTx(tx)     — 직렬화 (서명 대상 메시지)
 */

import { sha256, createSignature, verifySignature } from "./crypto-utils";
import type { Transaction, CoinbaseTx } from "./types";

// ============================================================
// 직렬화
// ============================================================

export function serializeTx(tx: Omit<Transaction, "id" | "signature">): string {
  return JSON.stringify({
    from:      tx.from,
    to:        tx.to,
    amount:    tx.amount,
    fee:       tx.fee,
    timestamp: tx.timestamp,
    nonce:     tx.nonce,
  });
}

export function calcTxId(tx: Omit<Transaction, "id">): string {
  return sha256(serializeTx(tx) + tx.signature);
}

// ============================================================
// TransactionBuilder
// ============================================================

export class TransactionBuilder {
  private from:      string = "";
  private to:        string = "";
  private amount:    number = 0;
  private fee:       number = 0;
  private nonce:     number = 0;

  setFrom(address: string):   this { this.from   = address; return this; }
  setTo(address: string):     this { this.to     = address; return this; }
  setAmount(amount: number):  this { this.amount  = amount;  return this; }
  setFee(fee: number):        this { this.fee     = fee;     return this; }
  setNonce(nonce: number):    this { this.nonce   = nonce;   return this; }

  /** 트랜잭션 서명 후 완성 */
  sign(privateKey: string, publicKey: string): Transaction {
    if (!this.from || !this.to)       throw new Error("from/to 주소 필수");
    if (this.amount <= 0)             throw new Error("amount > 0 필수");
    if (this.fee < 0)                 throw new Error("fee >= 0 필수");
    if (this.amount + this.fee <= 0)  throw new Error("amount + fee > 0 필수");

    const timestamp = Date.now();
    const partial: Omit<Transaction, "id" | "signature"> = {
      from:      this.from,
      to:        this.to,
      amount:    this.amount,
      fee:       this.fee,
      timestamp,
      nonce:     this.nonce,
    };

    const message   = serializeTx(partial);
    const signature = createSignature(privateKey, publicKey, message);
    const id        = sha256(message + signature);

    return { ...partial, id, signature };
  }
}

// ============================================================
// 코인베이스 트랜잭션 (채굴 보상)
// ============================================================

export function createCoinbaseTx(
  to:     string,
  amount: number,
  height: number
): CoinbaseTx {
  const timestamp = Date.now();
  const id        = sha256(`coinbase:${to}:${amount}:${height}:${timestamp}`);
  return { id, to, amount, height, timestamp };
}

// ============================================================
// 유효성 검증
// ============================================================

export interface TxValidationResult {
  valid:  boolean;
  errors: string[];
}

export function validateTx(tx: Transaction, publicKey: string): TxValidationResult {
  const errors: string[] = [];

  if (!tx.id)           errors.push("id 누락");
  if (!tx.from)         errors.push("from 누락");
  if (!tx.to)           errors.push("to 누락");
  if (tx.amount <= 0)   errors.push("amount must be > 0");
  if (tx.fee < 0)       errors.push("fee must be >= 0");
  if (!tx.signature)    errors.push("signature 누락");
  if (tx.from === tx.to) errors.push("self-transfer 불가");

  // 서명 검증
  if (tx.signature && publicKey) {
    const message = serializeTx(tx);
    if (!verifySignature(publicKey, message, tx.signature)) {
      errors.push("서명 검증 실패");
    }
  }

  // ID 재계산 검증
  if (tx.id) {
    const expected = sha256(serializeTx(tx) + tx.signature);
    if (expected !== tx.id) {
      errors.push("tx ID 불일치");
    }
  }

  return { valid: errors.length === 0, errors };
}

// ============================================================
// Transaction 클래스 (Phase 1: API 일관성 강화)
// ============================================================

/**
 * Transaction namespace — 메서드 기반 API
 *
 * 마이그레이션 전략:
 *  - 기존 함수는 호환성을 위해 유지 (Deprecation 경고)
 *  - 새로운 코드는 Transaction.* 메서드 사용
 *  - 6개월 후 기존 함수 제거 예정
 */
export const Transaction = {
  /**
   * 코인베이스 트랜잭션 생성 (채굴 보상)
   * @param to 수신자 주소
   * @param amount 보상 금액
   * @param height 블록 높이
   * @returns 코인베이스 트랜잭션
   *
   * @example
   * const coinbase = Transaction.createCoinbase("miner1", 50, 1);
   */
  createCoinbase(
    to:     string,
    amount: number,
    height: number
  ): CoinbaseTx {
    return createCoinbaseTx(to, amount, height);
  },

  /**
   * 트랜잭션 유효성 검증
   * @param tx 검증할 트랜잭션
   * @param publicKey 발신자의 공개키
   * @returns 검증 결과
   *
   * @example
   * const result = Transaction.validate(tx, publicKey);
   * if (!result.valid) console.error(result.errors);
   */
  validate(tx: Transaction, publicKey: string): TxValidationResult {
    return validateTx(tx, publicKey);
  },

  /**
   * 트랜잭션 직렬화
   * @param tx 직렬화할 트랜잭션 (ID와 서명 제외)
   * @returns JSON 문자열
   *
   * @example
   * const serialized = Transaction.serialize({ from: "addr1", to: "addr2", ... });
   */
  serialize(tx: Omit<Transaction, "id" | "signature">): string {
    return serializeTx(tx);
  },

  /**
   * 트랜잭션 ID 계산
   * @param tx 트랜잭션 (ID 제외)
   * @returns 계산된 트랜잭션 ID
   *
   * @example
   * const id = Transaction.calculateId({ from: "addr1", to: "addr2", ... });
   */
  calculateId(tx: Omit<Transaction, "id">): string {
    return calcTxId(tx);
  },
};

