  repeat: (s: Value, n: Value): Value => str_repeat(s, n),
  indexOf: (s: Value, sub: Value): Value => str_index_of(s, sub),
  padStart: (s: Value, width: Value, fill: Value): Value => str_pad_start(s, width, fill),
  padEnd: (s: Value, width: Value, fill: Value): Value => str_pad_end(s, width, fill),
  charAt: (s: Value, idx: Value): Value => str_char_at(s, idx),
