     1→/**
     2→ * FreeLang v4 StdLib — Regex Functions (3개 + 확장)
     3→ *
     4→ * 1. regex_match(s, pattern, flags?)  → bool | arr[str]
     5→ *    - flags 없으면 bool (패턴 일치 여부)
     6→ *    - flags에 "g" 포함 시 전체 매치 배열 반환
     7→ *
     8→ * 2. regex_split(s, pattern, flags?)  → arr[str]
     9→ *    - 정규식 구분자로 분리
    10→ *
    11→ * 3. regex_replace(s, pattern, repl, flags?) → str
    12→ *    - 정규식 패턴 치환
    13→ *    - flags에 "g" → 전체 치환, 없으면 첫 번째만
    14→ *
    15→ * + regex_test(s, pattern)    → bool
    16→ * + regex_groups(s, pattern)  → arr[str] (캡처 그룹)
    17→ * + regex_valid(pattern)      → bool
    18→ */
    19→
    20→import { Value, V, assertStr } from "./types";
    21→
    22→// ============================================================
    23→// 내부 헬퍼: 안전한 RegExp 생성
    24→// ============================================================
    25→
    26→function makeRegex(pattern: string, flags: string): RegExp {
    27→  try {
    28→    return new RegExp(pattern, flags);
    29→  } catch (e: any) {
    30→    throw new Error(`regex: 유효하지 않은 패턴 '${pattern}': ${e.message}`);
    31→  }
    32→}
    33→
    34→// ============================================================
    35→// 1. regex_match
    36→// ============================================================
    37→
    38→/**
    39→ * regex_match(s, pattern)         → bool   (단순 일치 여부)
    40→ * regex_match(s, pattern, "g")    → arr[str] (전체 매치 목록)
    41→ * regex_match(s, pattern, "gi")   → arr[str] (대소문자 무시 + 전체)
    42→ */
    43→export function regex_match(s: Value, pattern: Value, flags: Value = V.str("")): Value {
    44→  const str  = assertStr(s, "regex_match");
    45→  const pat  = assertStr(pattern, "regex_match");
    46→  const flgs = assertStr(flags, "regex_match");
    47→
    48→  if (flgs.includes("g")) {
    49→    // 전체 매치 모드
    50→    const re      = makeRegex(pat, flgs);
    51→    const matches = [...str.matchAll(re)].map((m) => V.str(m[0]));
    52→    return V.arr(matches);
    53→  } else {
    54→    // 단순 일치 여부
    55→    const re = makeRegex(pat, flgs);
    56→    return V.bool(re.test(str));
    57→  }
    58→}
    59→
    60→// ============================================================
    61→// 2. regex_split
    62→// ============================================================
    63→
    64→export function regex_split(s: Value, pattern: Value, flags: Value = V.str("")): Value {
    65→  const str  = assertStr(s, "regex_split");
    66→  const pat  = assertStr(pattern, "regex_split");
    67→  const flgs = assertStr(flags, "regex_split");
    68→
    69→  const re = makeRegex(pat, flgs);
    70→  return V.arr(str.split(re).map((p) => V.str(p)));
    71→}
    72→
    73→// ============================================================
    74→// 3. regex_replace
    75→// ============================================================
    76→
    77→/**
    78→ * regex_replace(s, pattern, repl)      → str   (첫 번째 매치 치환)
    79→ * regex_replace(s, pattern, repl, "g") → str   (전체 치환)
    80→ */
    81→export function regex_replace(
    82→  s:       Value,
    83→  pattern: Value,
    84→  repl:    Value,
    85→  flags:   Value = V.str("")
    86→): Value {
    87→  const str  = assertStr(s, "regex_replace");
    88→  const pat  = assertStr(pattern, "regex_replace");
    89→  const r    = assertStr(repl, "regex_replace");
    90→  const flgs = assertStr(flags, "regex_replace");
    91→
    92→  const re = makeRegex(pat, flgs);
    93→  return V.str(flgs.includes("g") ? str.replaceAll(re, r) : str.replace(re, r));
    94→}
    95→
    96→// ============================================================
    97→// 4. regex_test — 단순 bool 테스트
    98→// ============================================================
    99→
   100→export function regex_test(s: Value, pattern: Value, flags: Value = V.str("")): Value {
   101→  const str  = assertStr(s, "regex_test");
   102→  const pat  = assertStr(pattern, "regex_test");
   103→  const flgs = assertStr(flags, "regex_test");
   104→  return V.bool(makeRegex(pat, flgs).test(str));
   105→}
   106→
   107→// ============================================================
   108→// 5. regex_groups — 캡처 그룹 반환
   109→// ============================================================
   110→
   111→export function regex_groups(s: Value, pattern: Value, flags: Value = V.str("")): Value {
   112→  const str  = assertStr(s, "regex_groups");
   113→  const pat  = assertStr(pattern, "regex_groups");
   114→  const flgs = assertStr(flags, "regex_groups");
   115→
   116→  const re = makeRegex(pat, flgs);
   117→  const m  = str.match(re);
   118→  if (!m) return V.none();
   119→
   120→  // m[0] = 전체 매치, m[1..] = 캡처 그룹
   121→  const groups = m.slice(1).map((g) => (g !== undefined ? V.str(g) : V.none()));
   122→  return V.some(V.arr(groups));
   123→}
   124→
   125→// ============================================================
   126→// 6. regex_valid — 패턴 유효성 확인
   127→// ============================================================
   128→
   129→export function regex_valid(pattern: Value): Value {
   130→  const pat = assertStr(pattern, "regex_valid");
   131→  try {
   132→    new RegExp(pat);
   133→    return V.bool(true);
   134→  } catch {
   135→    return V.bool(false);
   136→  }
   137→}
   138→
   139→// ============================================================
   140→// 7. regex_count — 패턴 매치 횟수
   141→// ============================================================
   142→
   143→export function regex_count(s: Value, pattern: Value, flags: Value = V.str("g")): Value {
   144→  const str  = assertStr(s, "regex_count");
   145→  const pat  = assertStr(pattern, "regex_count");
   146→  const flgs = assertStr(flags, "regex_count");
   147→
   148→  // 항상 g 플래그 포함
   149→  const fStr = flgs.includes("g") ? flgs : flgs + "g";
   150→  const re   = makeRegex(pat, fStr);
   151→  return V.i32([...str.matchAll(re)].length);
   152→}
