  createTable: (db: Database, table: string, schema: Record<string, string>): void => db_create_table(db, table, schema),
  query: (db: Database, sql: string, params?: Value[]): Value => db_query(db, sql, params),
  insert: (db: Database, tableName: string, rowData: Record<string, Value>): Value => db_insert(db, tableName, rowData),
  update: (db: Database, tableName: string, setData: Record<string, Value>, where: string): Value => db_update(db, tableName, setData, where),
  delete: (db: Database, tableName: string, where: string): Value => db_delete(db, tableName, where),
  count: (db: Database, tableName: string, where?: string): Value => db_count(db, tableName, where),
  begin: (db: Database): void => db_begin(db),
  commit: (db: Database): Value => db_commit(db),
  rollback: (db: Database): Value => db_rollback(db),
} as const;

