/**
 * FreeLang v4 StdLib — 통합 테스트 (56개)
 *
 * Group 1. String Functions    (14개) T01~T14
 * Group 2. Functional          (10개) T15~T24
 * Group 3. Regex               ( 8개) T25~T32
 * Group 4. JSON                (12개) T33~T44
 * Group 5. Database            (12개) T45~T56
 */

import {
  // String
  str_len, str_upper, str_lower, str_trim,
  str_split, str_join, str_contains, str_starts_with, str_ends_with,
  str_replace, str_replace_all, str_slice, str_repeat, str_index_of,
  str_pad_start, str_pad_end, str_char_at, str_to_chars,
  // Functional
  compose, pipe, curry, memoize, memoize_tracked, partial, once, flip, identity, constant,
  // Regex
  regex_match, regex_split, regex_replace, regex_test, regex_groups, regex_valid, regex_count,
  // JSON
  json_parse, json_stringify, json_validate, json_pretty, json_get, json_merge,
  // Database
  db_create, db_create_table, db_query, db_insert, db_update, db_delete, db_count,
  db_begin, db_commit, db_rollback,
  // Types
  V, Value,
  Database,
} from "../src/index";

// ============================================================
// Group 1. String Functions
// ============================================================

describe("String Functions", () => {
  test("T01: str_len — 한글 포함 길이", () => {
    expect(str_len(V.str("hello"))).toEqual(V.i32(5));
    expect(str_len(V.str("안녕"))).toEqual(V.i32(2));
    expect(str_len(V.str(""))).toEqual(V.i32(0));
  });

  test("T02: str_upper / str_lower", () => {
    expect(str_upper(V.str("hello World"))).toEqual(V.str("HELLO WORLD"));
    expect(str_lower(V.str("HELLO World"))).toEqual(V.str("hello world"));
  });

  test("T03: str_trim — 앞뒤 공백 제거", () => {
    expect(str_trim(V.str("  hello  "))).toEqual(V.str("hello"));
    expect(str_trim(V.str("\t\n text \n"))).toEqual(V.str("text"));
  });

