describe("🆕 Namespace Object APIs (Phase 2)", () => {
  test("NS01: String.len / String.upper / String.lower", () => {
    expect(String.len(V.str("hello"))).toEqual(V.i32(5));
    expect(String.upper(V.str("hello"))).toEqual(V.str("HELLO"));
    expect(String.lower(V.str("HELLO"))).toEqual(V.str("hello"));
