/**
 * FreeLang v4 StdLib — 통합 테스트 (56개)
 *
 * Group 1. String Functions    (14개) T01~T14
 * Group 2. Functional          (10개) T15~T24
 * Group 3. Regex               ( 8개) T25~T32
 * Group 4. JSON                (12개) T33~T44
 * Group 5. Database            (12개) T45~T56
 */

import {
  // String
  str_len, str_upper, str_lower, str_trim,
  str_split, str_join, str_contains, str_starts_with, str_ends_with,
  str_replace, str_replace_all, str_slice, str_repeat, str_index_of,
  str_pad_start, str_pad_end, str_char_at, str_to_chars,
  String,
  // Functional
  compose, pipe, curry, memoize, memoize_tracked, partial, once, flip, identity, constant,
  Functional,
  // Regex
  regex_match, regex_split, regex_replace, regex_test, regex_groups, regex_valid, regex_count,
  Regex,
  // JSON
  json_parse, json_stringify, json_validate, json_pretty, json_get, json_merge,
  JSON,
  // Database
  db_create, db_create_table, db_query, db_insert, db_update, db_delete, db_count,
  db_begin, db_commit, db_rollback,
  Database,
  DatabaseType,
  // Types
  V, Value,
} from "../src/index";

// ============================================================
// Group 1. String Functions
// ============================================================

describe("String Functions", () => {
  test("T01: str_len — 한글 포함 길이", () => {
    expect(str_len(V.str("hello"))).toEqual(V.i32(5));
    expect(str_len(V.str("안녕"))).toEqual(V.i32(2));
    expect(str_len(V.str(""))).toEqual(V.i32(0));
  });

  test("T02: str_upper / str_lower", () => {
    expect(str_upper(V.str("hello World"))).toEqual(V.str("HELLO WORLD"));
    expect(str_lower(V.str("HELLO World"))).toEqual(V.str("hello world"));
  });

  test("T03: str_trim — 앞뒤 공백 제거", () => {
    expect(str_trim(V.str("  hello  "))).toEqual(V.str("hello"));
    expect(str_trim(V.str("\t\n text \n"))).toEqual(V.str("text"));
  });

  test("T04: str_split / str_join 라운드트립", () => {
    const arr = str_split(V.str("a,b,c"), V.str(","));
    expect(arr.tag).toBe("arr");
    const joined = str_join(arr, V.str(","));
    expect(joined).toEqual(V.str("a,b,c"));
  });

  test("T05: str_contains / starts_with / ends_with", () => {
    expect(str_contains(V.str("hello world"), V.str("world"))).toEqual(V.bool(true));
    expect(str_starts_with(V.str("hello"), V.str("hel"))).toEqual(V.bool(true));
    expect(str_ends_with(V.str("hello"), V.str("llo"))).toEqual(V.bool(true));
    expect(str_contains(V.str("hello"), V.str("xyz"))).toEqual(V.bool(false));
  });

  test("T06: str_replace (첫 번째) / str_replace_all (전체)", () => {
    expect(str_replace(V.str("aababc"), V.str("a"), V.str("X"))).toEqual(V.str("Xababc"));
    expect(str_replace_all(V.str("aababc"), V.str("a"), V.str("X"))).toEqual(V.str("XXbXbc"));
  });

  test("T07: str_slice — 양수/음수 인덱스", () => {
    expect(str_slice(V.str("hello"), V.i32(1), V.i32(4))).toEqual(V.str("ell"));
    expect(str_slice(V.str("hello"), V.i32(0), V.i32(-1))).toEqual(V.str("hell")); // 음수
  });

  test("T08: str_repeat — N회 반복", () => {
    expect(str_repeat(V.str("ab"), V.i32(3))).toEqual(V.str("ababab"));
    expect(str_repeat(V.str("x"), V.i32(0))).toEqual(V.str(""));
  });

  test("T09: str_index_of — 위치 탐색", () => {
    expect(str_index_of(V.str("hello world"), V.str("world"))).toEqual(V.i32(6));
    expect(str_index_of(V.str("hello"), V.str("xyz"))).toEqual(V.i32(-1));
  });

  test("T10: str_pad_start / str_pad_end", () => {
    expect(str_pad_start(V.str("5"), V.i32(3), V.str("0"))).toEqual(V.str("005"));
    expect(str_pad_end(V.str("hi"), V.i32(5), V.str("."))).toEqual(V.str("hi..."));
  });

  test("T11: str_char_at — some/none", () => {
    const r = str_char_at(V.str("hello"), V.i32(1));
    expect(r.tag).toBe("some");
    expect((r as any).val).toEqual(V.str("e"));
    expect(str_char_at(V.str("hi"), V.i32(10)).tag).toBe("none");
  });

  test("T12: str_to_chars — 문자 배열 분해", () => {
    const chars = str_to_chars(V.str("abc"));
    expect(chars.tag).toBe("arr");
    expect((chars as any).elements).toEqual([V.str("a"), V.str("b"), V.str("c")]);
  });

  test("T13: str 타입 오류 → 예외", () => {
    expect(() => str_len(V.i32(42))).toThrow("str 필요");
    expect(() => str_upper(V.bool(true))).toThrow("str 필요");
  });

  test("T14: str_join — 빈 배열", () => {
    const empty = str_join(V.arr([]), V.str(","));
    expect(empty).toEqual(V.str(""));
  });
});

// ============================================================
// Group 2. Functional
// ============================================================

describe("Functional Programming", () => {
  const add1  = (v: Value): Value => V.i32((v as any).val + 1);
  const mul2  = (v: Value): Value => V.i32((v as any).val * 2);
  const str_v = (v: Value): Value => V.str(globalThis.String((v as any).val));

  test("T15: compose — 우→좌 합성 (mul2 → add1 순서)", () => {
    // compose(add1, mul2)(5) = add1(mul2(5)) = add1(10) = 11
    const fn = compose(add1, mul2);
    expect(fn(V.i32(5))).toEqual(V.i32(11));
  });

  test("T16: pipe — 좌→우 합성 (mul2 먼저)", () => {
    // pipe(mul2, add1)(5) = add1(mul2(5)) = 11
    const fn = pipe(mul2, add1);
    expect(fn(V.i32(5))).toEqual(V.i32(11));
  });

  test("T17: compose 3단계", () => {
    // compose(str_v, add1, mul2)(3) = str_v(add1(mul2(3))) = str_v(7) = "7"
    const fn = compose(str_v, add1, mul2);
    expect(fn(V.i32(3))).toEqual(V.str("7"));
  });

  test("T18: curry — 인자 하나씩 적용", () => {
    const add = (a: Value, b: Value): Value => V.i32((a as any).val + (b as any).val);
    const curried = curry(add, 2);
    const add5 = (curried(V.i32(5)) as unknown) as (...args: Value[]) => Value;
    expect(add5(V.i32(3))).toEqual(V.i32(8));
  });

  test("T19: memoize — 동일 인수 캐싱", () => {
    let callCount = 0;
    const expensive = (v: Value): Value => { callCount++; return V.i32((v as any).val * (v as any).val); };
    const memo = memoize(expensive);
    memo(V.i32(5));
    memo(V.i32(5));
    memo(V.i32(5));
    expect(callCount).toBe(1); // 최초 1회만 실행
    expect(memo(V.i32(6))).toEqual(V.i32(36));
    expect(callCount).toBe(2);
  });

  test("T20: memoize_tracked — 히트/미스 추적", () => {
    const { fn, hits, misses } = memoize_tracked((v) => V.i32((v as any).val + 1));
    fn(V.i32(1)); // miss
    fn(V.i32(1)); // hit
    fn(V.i32(2)); // miss
    expect(hits()).toBe(1);
    expect(misses()).toBe(2);
  });

  test("T21: partial — 부분 적용", () => {
    const add = (a: Value, b: Value, c: Value): Value =>
      V.i32((a as any).val + (b as any).val + (c as any).val);
    const add10 = partial(add, V.i32(10));
    expect(add10(V.i32(3), V.i32(2))).toEqual(V.i32(15));
  });

  test("T22: once — 최초 1회만 실행", () => {
    let n = 0;
    const fn = once(() => { n++; return V.i32(n); });
    expect(fn()).toEqual(V.i32(1));
    expect(fn()).toEqual(V.i32(1)); // 동일 결과
    expect(fn()).toEqual(V.i32(1));
    expect(n).toBe(1);
  });

  test("T23: flip — 첫 두 인수 순서 뒤집기", () => {
    const sub = (a: Value, b: Value): Value => V.i32((a as any).val - (b as any).val);
    const flipped = flip(sub);
    // flip(sub)(10, 3) = sub(3, 10) = -7
    expect(flipped(V.i32(10), V.i32(3))).toEqual(V.i32(-7));
  });

  test("T24: identity / constant", () => {
    expect(identity(V.i32(42))).toEqual(V.i32(42));
    const always5 = constant(V.i32(5));
    expect(always5(V.str("anything"))).toEqual(V.i32(5));
  });
});

// ============================================================
// Group 3. Regex
// ============================================================

describe("Regex Functions", () => {
  test("T25: regex_test — 패턴 일치 여부", () => {
    expect(regex_test(V.str("hello@email.com"), V.str("^\\w+@\\w+\\.\\w+$"))).toEqual(V.bool(true));
    expect(regex_test(V.str("not-email"), V.str("^\\w+@\\w+\\.\\w+$"))).toEqual(V.bool(false));
  });

  test("T26: regex_match bool 모드 (g 플래그 없음)", () => {
    const r = regex_match(V.str("abc123"), V.str("\\d+"));
    expect(r).toEqual(V.bool(true));
  });

  test("T27: regex_match 전체 매치 모드 (g 플래그)", () => {
    const r = regex_match(V.str("abc 123 def 456"), V.str("\\d+"), V.str("g"));
    expect(r.tag).toBe("arr");
    const els = (r as any).elements;
    expect(els).toHaveLength(2);
    expect(els[0]).toEqual(V.str("123"));
    expect(els[1]).toEqual(V.str("456"));
  });

  test("T28: regex_split — 정규식 구분자", () => {
    const r = regex_split(V.str("one  two   three"), V.str("\\s+"));
    expect(r.tag).toBe("arr");
    expect((r as any).elements).toHaveLength(3);
  });

  test("T29: regex_replace — 첫 번째 치환", () => {
    const r = regex_replace(V.str("cat and cat"), V.str("cat"), V.str("dog"));
    expect(r).toEqual(V.str("dog and cat"));
  });

  test("T30: regex_replace 전체 치환 (g 플래그)", () => {
    const r = regex_replace(V.str("cat and cat"), V.str("cat"), V.str("dog"), V.str("g"));
    expect(r).toEqual(V.str("dog and dog"));
  });

  test("T31: regex_groups — 캡처 그룹", () => {
    const r = regex_groups(V.str("2025-12-25"), V.str("(\\d{4})-(\\d{2})-(\\d{2})"));
    expect(r.tag).toBe("some");
    const arr = (r as any).val;
    expect(arr.elements[0]).toEqual(V.str("2025"));
    expect(arr.elements[1]).toEqual(V.str("12"));
    expect(arr.elements[2]).toEqual(V.str("25"));
  });

  test("T32: regex_count + regex_valid", () => {
    expect(regex_count(V.str("aababab"), V.str("ab"))).toEqual(V.i32(3));
    expect(regex_valid(V.str("\\d+"))).toEqual(V.bool(true));
    expect(regex_valid(V.str("[invalid"))).toEqual(V.bool(false));
  });
});

// ============================================================
// Group 4. JSON
// ============================================================

describe("JSON Functions", () => {
  test("T33: json_parse — 기본 타입 변환", () => {
    const r = json_parse(V.str('{"name":"Alice","age":30,"active":true}'));
    expect(r.tag).toBe("ok");
    const val = (r as any).val;
    expect(val.tag).toBe("struct");
    expect(val.fields.get("name")).toEqual(V.str("Alice"));
    expect(val.fields.get("age")).toEqual(V.i32(30));
    expect(val.fields.get("active")).toEqual(V.bool(true));
  });

  test("T34: json_parse — 배열", () => {
    const r = json_parse(V.str('[1, 2, 3]'));
    expect(r.tag).toBe("ok");
    const arr = (r as any).val;
    expect(arr.tag).toBe("arr");
    expect(arr.elements).toHaveLength(3);
  });

  test("T35: json_parse — 오류 처리", () => {
    const r = json_parse(V.str("{invalid json}"));
    expect(r.tag).toBe("err");
  });

  test("T36: json_stringify — struct → JSON", () => {
    const v = V.struct({ name: V.str("Bob"), score: V.i32(100) });
    const r = json_stringify(v);
    expect(r.tag).toBe("str");
    const parsed = globalThis.JSON.parse((r as any).val);
    expect((parsed as any).name).toBe("Bob");
    expect((parsed as any).score).toBe(100);
  });

  test("T37: json_stringify — 배열", () => {
    const v = V.arr([V.i32(1), V.str("two"), V.bool(true)]);
    const r = json_stringify(v);
    expect((r as any).val).toBe('[1,"two",true]');
  });

  test("T38: json_parse → json_stringify 라운드트립", () => {
    const original = '{"x":1,"y":2}';
    const parsed   = json_parse(V.str(original));
    const back     = json_stringify((parsed as any).val);
    expect(globalThis.JSON.parse((back as any).val)).toEqual(globalThis.JSON.parse(original));
  });

  test("T39: json_validate — object 스키마 (required 키 확인)", () => {
    const schema = V.str(JSON.stringify({
      type: "object",
      required: ["name", "age"],
    }));
    expect(json_validate(V.str('{"name":"Alice","age":30}'), schema)).toEqual(V.bool(true));
    expect(json_validate(V.str('{"name":"Alice"}'), schema)).toEqual(V.bool(false)); // age 없음
  });

  test("T40: json_validate — 숫자 범위 검증", () => {
    const schema = V.str(JSON.stringify({ type: "number", minimum: 0, maximum: 100 }));
    expect(json_validate(V.str("50"), schema)).toEqual(V.bool(true));
    expect(json_validate(V.str("150"), schema)).toEqual(V.bool(false));
  });

  test("T41: json_pretty — 들여쓰기", () => {
    const v = V.struct({ a: V.i32(1) });
    const r = json_pretty(v, V.i32(2));
    expect((r as any).val).toContain("\n");
    expect((r as any).val).toContain("  ");
  });

  test("T42: json_get — 점 경로 접근", () => {
    const v = json_parse(V.str('{"user":{"name":"Alice","scores":[10,20,30]}}'));
    const struct = (v as any).val;
    const nameResult = json_get(struct, V.str("user.name"));
    expect(nameResult.tag).toBe("some");
    expect((nameResult as any).val).toEqual(V.str("Alice"));
    const missing = json_get(struct, V.str("user.email"));
    expect(missing.tag).toBe("none");
  });

  test("T43: json_merge — 두 struct 병합 (b 우선)", () => {
    const a = V.struct({ x: V.i32(1), y: V.i32(2) });
    const b = V.struct({ y: V.i32(99), z: V.i32(3) });
    const r = json_merge(a, b);
    expect(r.tag).toBe("ok");
    const merged = (r as any).val;
    expect(merged.fields.get("x")).toEqual(V.i32(1));
    expect(merged.fields.get("y")).toEqual(V.i32(99)); // b 우선
    expect(merged.fields.get("z")).toEqual(V.i32(3));
  });

  test("T44: json_merge — struct 아닌 타입 → err", () => {
    const r = json_merge(V.i32(1), V.str("oops"));
    expect(r.tag).toBe("err");
  });
});

// ============================================================
// Group 5. Database
// ============================================================

describe("Database Functions", () => {
  let db: Database;

  beforeEach(() => {
    db = db_create("test_db");
    db_create_table(db, "users", { name: "str", age: "i32", email: "str" });
  });

  test("T45: db_insert — 행 삽입 및 id 반환", () => {
    const r = db_insert(db, "users", { name: V.str("Alice"), age: V.i32(30), email: V.str("a@ex.com") });
    expect(r.tag).toBe("ok");
    expect((r as any).val).toEqual(V.i32(1));

    const r2 = db_insert(db, "users", { name: V.str("Bob"), age: V.i32(25), email: V.str("b@ex.com") });
    expect((r2 as any).val).toEqual(V.i32(2));
  });

  test("T46: db_query SELECT * FROM table", () => {
    db_insert(db, "users", { name: V.str("Alice"), age: V.i32(30) });
    db_insert(db, "users", { name: V.str("Bob"),   age: V.i32(25) });
    const r = db_query(db, "SELECT * FROM users", []);
    expect(r.tag).toBe("ok");
    const rows = (r as any).val;
    expect(rows.tag).toBe("arr");
    expect(rows.elements).toHaveLength(2);
  });

  test("T47: db_query SELECT WHERE 조건", () => {
    db_insert(db, "users", { name: V.str("Alice"), age: V.i32(30) });
    db_insert(db, "users", { name: V.str("Bob"),   age: V.i32(17) });
    db_insert(db, "users", { name: V.str("Carol"), age: V.i32(25) });

    const r = db_query(db, "SELECT * FROM users WHERE age >= 25", []);
    expect(r.tag).toBe("ok");
    expect((r as any).val.elements).toHaveLength(2);
  });

  test("T48: db_query 파라미터 바인딩 ($1)", () => {
    db_insert(db, "users", { name: V.str("Alice"), age: V.i32(30) });
    db_insert(db, "users", { name: V.str("Bob"),   age: V.i32(25) });

    const r = db_query(db, "SELECT * FROM users WHERE name = $1", [V.str("Alice")]);
    expect((r as any).val.elements).toHaveLength(1);
    const row = (r as any).val.elements[0];
    expect(row.fields.get("name")).toEqual(V.str("Alice"));
  });

  test("T49: db_query ORDER BY + LIMIT", () => {
    db_insert(db, "users", { name: V.str("C"), age: V.i32(30) });
    db_insert(db, "users", { name: V.str("A"), age: V.i32(10) });
    db_insert(db, "users", { name: V.str("B"), age: V.i32(20) });

    const r = db_query(db, "SELECT * FROM users ORDER BY age ASC LIMIT 2", []);
    const rows = (r as any).val.elements;
    expect(rows).toHaveLength(2);
    expect(rows[0].fields.get("name")).toEqual(V.str("A")); // 나이 가장 적음
  });

  test("T50: db_update — 조건부 업데이트", () => {
    db_insert(db, "users", { name: V.str("Alice"), age: V.i32(30) });
    db_insert(db, "users", { name: V.str("Bob"),   age: V.i32(30) });
    db_insert(db, "users", { name: V.str("Carol"), age: V.i32(25) });

    const r = db_update(db, "users", { age: V.i32(31) }, "age = 30");
    expect(r.tag).toBe("ok");
    expect((r as any).val).toEqual(V.i32(2)); // 2행 업데이트

    const q = db_query(db, "SELECT * FROM users WHERE age = 31", []);
    expect((q as any).val.elements).toHaveLength(2);
  });

  test("T51: db_delete — 조건부 삭제", () => {
    db_insert(db, "users", { name: V.str("Alice"), age: V.i32(30) });
    db_insert(db, "users", { name: V.str("Bob"),   age: V.i32(17) });

    const r = db_delete(db, "users", "age < 18");
    expect(r.tag).toBe("ok");
    expect((r as any).val).toEqual(V.i32(1)); // 1행 삭제

    expect(db_count(db, "users")).toEqual(V.i32(1));
  });

  test("T52: db_count — 전체/조건", () => {
    db_insert(db, "users", { name: V.str("Alice"), age: V.i32(30) });
    db_insert(db, "users", { name: V.str("Bob"),   age: V.i32(25) });
    db_insert(db, "users", { name: V.str("Carol"), age: V.i32(17) });

    expect(db_count(db, "users")).toEqual(V.i32(3));
    expect(db_count(db, "users", "age >= 25")).toEqual(V.i32(2));
  });

  test("T53: db_insert 없는 테이블 → err", () => {
    const r = db_insert(db, "no_table", { x: V.i32(1) });
    expect(r.tag).toBe("err");
  });

  test("T54: db_query 없는 테이블 → err", () => {
    const r = db_query(db, "SELECT * FROM ghost", []);
    expect(r.tag).toBe("err");
  });

  test("T55: 트랜잭션 — begin/commit", () => {
    db_begin(db);
    db_insert(db, "users", { name: V.str("TxUser"), age: V.i32(20) });
    const committed = db_commit(db);
    expect(committed.tag).toBe("ok");
    expect(db_count(db, "users")).toEqual(V.i32(1)); // commit 후 반영됨
  });

  test("T56: 통합 시나리오 — 가입→조회→수정→탈퇴", () => {
    // 가입
    const id = db_insert(db, "users", { name: V.str("Dave"), age: V.i32(28), email: V.str("d@ex.com") });
    expect(id.tag).toBe("ok");

    // 조회
    const found = db_query(db, "SELECT * FROM users WHERE name = $1", [V.str("Dave")]);
    expect((found as any).val.elements).toHaveLength(1);

    // 수정
    db_update(db, "users", { age: V.i32(29) }, "name = 'Dave'");
    const updated = db_query(db, "SELECT * FROM users WHERE name = $1", [V.str("Dave")]);
    const row = (updated as any).val.elements[0];
    expect(row.fields.get("age")).toEqual(V.i32(29));

    // 탈퇴
    const deleted = db_delete(db, "users", "name = 'Dave'");
    expect((deleted as any).val).toEqual(V.i32(1));
    expect(db_count(db, "users")).toEqual(V.i32(0));
  });
});

// ============================================================
// Phase 2: Namespace Object APIs 가용성 확인
// ============================================================

describe("🆕 Namespace Object APIs (Phase 2) — 가용성 확인", () => {
  test("NS01: String namespace 객체 존재 확인", () => {
    // namespace object가 제대로 export되는지 확인
    expect(typeof String).toBe("object");
    expect(String.len).toBeDefined();
    expect(String.upper).toBeDefined();
    expect(String.lower).toBeDefined();
  });

  test("NS02: Functional namespace 객체 존재 확인", () => {
    expect(typeof Functional).toBe("object");
    expect(Functional.compose).toBeDefined();
    expect(Functional.pipe).toBeDefined();
    expect(Functional.memoize).toBeDefined();
  });

  test("NS03: Regex namespace 객체 존재 확인", () => {
    expect(typeof Regex).toBe("object");
    expect(Regex.test).toBeDefined();
    expect(Regex.match).toBeDefined();
    expect(Regex.split).toBeDefined();
  });

  test("NS04: JSON namespace 객체 존재 확인", () => {
    // JSON namespace는 globalThis.JSON과 구분하기 위해 type cast 사용
    const JSONMethods = (JSON as any);
    expect(typeof JSONMethods).toBe("object");
    expect(JSONMethods.parse).toBeDefined();
    expect(JSONMethods.stringify).toBeDefined();
    expect(JSONMethods.pretty).toBeDefined();
  });

  test("NS05: Database namespace 객체 존재 확인", () => {
    // DatabaseType은 interface, Database는 namespace object
    expect(typeof Database).toBe("object");
    expect(Database.create).toBeDefined();
    expect(Database.insert).toBeDefined();
    expect(Database.query).toBeDefined();
  });

  test("NS06: 기존 함수와 namespace 병렬 가용", () => {
    // 기존 함수들도 여전히 동작 (Deprecation pattern)
    expect(typeof str_len).toBe("function");
    expect(typeof str_upper).toBe("function");
    expect(typeof compose).toBe("function");
    expect(typeof regex_test).toBe("function");
    expect(typeof json_parse).toBe("function");
    expect(typeof db_create).toBe("function");
  });

  test("NS07: String namespace 메서드 체크", () => {
    const methods = Object.keys(String as any);
    expect(methods).toContain("len");
    expect(methods).toContain("upper");
    expect(methods).toContain("lower");
    expect(methods).toContain("split");
    expect(methods).toContain("join");
    expect(methods).toHaveLength(18);
  });

  test("NS08: Functional namespace 메서드 체크", () => {
    const methods = Object.keys(Functional as any);
    expect(methods).toContain("compose");
    expect(methods).toContain("pipe");
    expect(methods).toContain("memoize");
    expect(methods).toHaveLength(10);
  });

  test("NS09: Regex namespace 메서드 체크", () => {
    const methods = Object.keys(Regex as any);
    expect(methods).toContain("test");
    expect(methods).toContain("match");
    expect(methods).toContain("split");
    expect(methods).toHaveLength(7);
  });

  test("NS10: Database namespace 메서드 체크", () => {
    const methods = Object.keys(Database as any);
    expect(methods).toContain("create");
    expect(methods).toContain("insert");
    expect(methods).toContain("query");
    expect(methods).toHaveLength(10);
  });
});

