#!/usr/bin/env node
/**
 * FreeLang v4 ORM — CLI 진입점
 * Usage: npx ts-node src/main.ts <file.fl> [options]
 */

import * as fs from "fs";
import { ORMRunner } from "./orm-vm";

function main(): void {
  const args = process.argv.slice(2);

  if (args.length === 0 || args[0] === "--help") {
    console.log("FreeLang v4 ORM — AI-First ORM for FreeLang");
    console.log("Usage: freelang-orm <file.fl> [options]");
    console.log("");
    console.log("ORM 내장 함수 (21개):");
    console.log("  db_define(table, schema)          — 모델 정의");
    console.log("  db_insert(table, data)            — 레코드 삽입");
    console.log("  db_find(table, id)                — ID로 조회");
    console.log("  db_find_all(table)                — 전체 조회");
    console.log("  db_where(table, field, op, val)   — 조건 조회");
    console.log("  db_update(table, id, data)        — 업데이트");
    console.log("  db_delete(table, id)              — 삭제");
    console.log("  db_count(table)                   — 레코드 수");
    console.log("  db_query(table)                   — 쿼리 객체 생성");
    console.log("  db_filter(q, field, op, val)      — 필터 추가");
    console.log("  db_order(q, field, dir)           — 정렬");
    console.log("  db_limit(q, n)                    — 개수 제한");
    console.log("  db_offset(q, n)                   — 오프셋");
    console.log("  db_exec(q)                        — 쿼리 실행");
    console.log("  db_join(lt, rt, lk, rk)           — INNER JOIN");
    console.log("  db_left_join(lt, rt, lk, rk)      — LEFT JOIN");
    console.log("  db_belongs_to(child, parent, fk)  — belongs_to 관계");
    console.log("  db_has_many(parent, child, fk)    — has_many 관계");
    console.log("  db_eager_load(records, rel)       — Eager 로딩 (N+1 방지)");
    console.log("  db_batch_load(table, field, ids)  — 배치 로딩");
    console.log("  db_stats(table)                   — 테이블 통계");
    console.log("  db_tables()                       — 전체 테이블 목록");
    console.log("");
    console.log("Options:");
    console.log("  --no-check   타입 체크 건너뛰기");
    console.log("  --dump-bc    바이트코드 덤프");
    process.exit(0);
  }

  const file = args[0];
  const noCheck = args.includes("--no-check");
  const dumpBc = args.includes("--dump-bc");

  let source: string;
  try {
    source = fs.readFileSync(file, "utf-8");
  } catch {
    console.error(`error: cannot read '${file}'`);
    process.exit(1);
  }

  const runner = new ORMRunner();
  runner.run(source, { noCheck, dumpBc });
}

main();

