/**
 * FreeLang v4 ORM — VM 확장
 * 런타임 패치(monkey-patch) 방식으로 ORM 내장 함수 주입
 *
 * ORM 내장 함수 (21개):
 *   db_define, db_insert, db_find, db_find_all,
 *   db_where, db_update, db_delete, db_count,
 *   db_query, db_filter, db_order, db_limit, db_offset, db_exec,
 *   db_join, db_left_join,
 *   db_belongs_to, db_has_many,
 *   db_eager_load, db_batch_load,
 *   db_stats, db_tables
 */

import { Lexer } from "../../freelang-v4/src/lexer";
import { Parser } from "../../freelang-v4/src/parser";
import { TypeChecker } from "../../freelang-v4/src/checker";
import { Compiler, Chunk } from "../../freelang-v4/src/compiler";
import { VM, Value } from "../../freelang-v4/src/vm";

import { ORMEngine, QueryDescriptor, Row } from "./orm-engine";

// ============================================================
// Value ↔ JS 변환 헬퍼
// ============================================================

function jsToValue(v: any): Value {
  if (v === null || v === undefined) return { tag: "none" };
  if (typeof v === "boolean") return { tag: "bool", val: v };
  if (typeof v === "number") {
    return Number.isInteger(v) ? { tag: "i32", val: v } : { tag: "f64", val: v };
  }
  if (typeof v === "string") return { tag: "str", val: v };
  if (Array.isArray(v)) return { tag: "arr", val: v.map(jsToValue) };
  if (typeof v === "object") {
    const fields = new Map<string, Value>();
    for (const [k, val] of Object.entries(v)) {
      fields.set(k, jsToValue(val));
    }
    return { tag: "struct", fields };
  }
  return { tag: "str", val: String(v) };
}

function valueToJs(v: Value): any {
  switch (v.tag) {
    case "i32": case "f64": return (v as any).val;
    case "str":  return (v as any).val;
    case "bool": return (v as any).val;
    case "void": return null;

