    const { tokens, errors: lexErrors } = new Lexer(source).tokenize();
    if (lexErrors.length > 0) {
      for (const e of lexErrors) console.error(`lex:${e.line}: ${e.message}`);
      process.exit(1);
    }

    // 2. Parse
    const { program, errors: parseErrors } = new Parser(tokens).parse();
    if (parseErrors.length > 0) {
      for (const e of parseErrors) console.error(`parse:${e.line}: ${e.message}`);
      process.exit(1);
    }

    // 3. TypeCheck (optional)
    if (!options.noCheck) {
      const errors = new TypeChecker().check(program);
      if (errors.length > 0) {
        for (const e of errors) console.error(`type:${e.line}: ${e.message}`);
        process.exit(1);
      }
    }

    // 4. Compile
    const chunk = new Compiler().compile(program);

    if (options.dumpBc) {
      console.log(`--- bytecode (${chunk.code.length} bytes) ---`);
      console.log(`constants: ${JSON.stringify(chunk.constants)}`);
      process.exit(0);
    }

    // 5. VM 실행 — ORM 내장 함수 monkey-patch
    const vm = new VM() as any;
    const ormHandler = makeORMHandler(this.orm);
    const originalCallBuiltin = vm.callBuiltin.bind(vm);

    vm.callBuiltin = (name: string, args: Value[]): Value => {
      const result = ormHandler(name, args);
      if (result !== null) return result;
      return originalCallBuiltin(name, args);
    };

    const { output, error } = vm.run(chunk);
    for (const line of output) console.log(line);
    if (error) { console.error(error); process.exit(1); }
  }
}

