     1→/**
     2→ * FreeLang v4 Crypto Functions — 5개 내장 함수
     3→ *
     4→ * ╔══════════════════════════════════════════════╗
     5→ * ║  제국의 방패: Hardened Security Runtime       ║
     6→ * ╠══════════════════════════════════════════════╣
     7→ * ║  1. hash    — SHA-256/512 데이터 지문         ║
     8→ * ║  2. hmac    — HMAC-SHA256 메시지 인증         ║
     9→ * ║  3. encrypt — AES-256-GCM 인증 암호화         ║
    10→ * ║  4. decrypt — AES-256-GCM 복호화             ║
    11→ * ║  5. uuid    — UUID v4 고유 식별자             ║
    12→ * ╠══════════════════════════════════════════════╣
    13→ * ║  보안 원칙:                                   ║
    14→ * ║  · Constant-time 비교 (타이밍 공격 방지)       ║
    15→ * ║  · Zero-fill on Drop (메모리 흔적 제거)        ║
    16→ * ║  · 매번 새 IV/nonce (재전송 공격 방지)         ║
    17→ * ║  · GCM authTag 포함 (무결성 검증)             ║
    18→ * ╚══════════════════════════════════════════════╝
    19→ *
    20→ * 암호화 출력 형식:
    21→ *   "<iv_hex>:<authTag_hex>:<ciphertext_hex>"
    22→ *
    23→ * VM 구조: FreeLang v4 Value = { tag: string, ... }
    24→ */
    25→
    26→import * as crypto from "crypto";
    27→import { Value } from "../../freelang-v4/src/vm";
    28→
    29→// ============================================================
    30→// 상수
    31→// ============================================================
    32→
    33→const AES_ALGO     = "aes-256-gcm" as const;
    34→const IV_BYTES     = 12;  // GCM 권장 96-bit IV
    35→const KEY_BYTES    = 32;  // AES-256 = 32 bytes
    36→const TAG_BYTES    = 16;  // GCM authTag 128-bit
    37→const SEPARATOR    = ":";
    38→
    39→type SupportedHash = "sha256" | "sha512" | "sha1" | "md5";
    40→const HASH_ALGOS: SupportedHash[] = ["sha256", "sha512", "sha1", "md5"];
    41→const WEAK_ALGOS  = new Set(["md5", "sha1"]);
    42→
    43→// ============================================================
    44→// 내부 헬퍼
    45→// ============================================================
    46→
    47→function strVal(v: Value, fn: string): string {
    48→  if (v.tag === "str") return (v as any).val;
    49→  throw new Error(`${fn}: string 인수가 필요합니다 (got ${v.tag})`);
    50→}
    51→
    52→function optStrVal(v: Value | undefined, fn: string): string | undefined {
    53→  if (v === undefined) return undefined;
    54→  return strVal(v, fn);
    55→}
    56→
    57→/**
    58→ * 키를 정확히 32 bytes로 정규화
    59→ * 짧으면 SHA-256 stretch, 길면 SHA-256 축약
    60→ * 사용 후 버퍼를 0으로 덮어씀 (Zero-fill on Drop)
    61→ */
    62→function deriveKey(rawKey: string): Buffer {
    63→  const keyBuf = Buffer.from(rawKey, "utf-8");
    64→  if (keyBuf.length === KEY_BYTES) return keyBuf;
    65→  // PBKDF-lite: SHA-256 stretch/shrink
    66→  return crypto.createHash("sha256").update(keyBuf).digest();
    67→}
    68→
    69→/**
    70→ * Constant-time 문자열 비교 (타이밍 공격 방지)
    71→ */
    72→function safeEqual(a: string, b: string): boolean {
    73→  const bufA = Buffer.from(a);
    74→  const bufB = Buffer.from(b);
    75→  if (bufA.length !== bufB.length) {
    76→    // 길이가 달라도 동일 시간 소비를 위해 임시 비교 수행
    77→    crypto.timingSafeEqual(
    78→      Buffer.alloc(bufA.length),
    79→      Buffer.alloc(bufA.length)
    80→    );
    81→    return false;
    82→  }
    83→  return crypto.timingSafeEqual(bufA, bufB);
    84→}
    85→
    86→/**
    87→ * 버퍼를 0으로 덮어씀 (Zero-fill on Drop)
