});

test("hmac — 다른 키 → 다른 MAC (키 격리)", () => {
  const a = crypto_hmac([strArg("data"), strArg("key1")]);
  const b = crypto_hmac([strArg("data"), strArg("key2")]);
  expectFalse(str(a) === str(b), "키 격리 실패");
