    11→import * as crypto from "crypto";
    12→import { fl_sha256, fl_hmac, fl_base64_encode, fl_base64_decode } from "./crypto-engine";
    13→
    14→// ============================================================
    15→// 1. 비밀번호 해싱 (PBKDF2 스타일)
    16→// ============================================================
    17→
    18→export interface PasswordHash {
    19→  hash: string;
    20→  salt: string;
    21→  iterations: number;
    22→  algorithm: string;
    23→}
    24→
    25→/**
    26→ * PBKDF2 기반 비밀번호 해싱
    27→ * @param password 평문 비밀번호
    28→ * @param saltBytes 소금 바이트 수 (기본: 16)
    29→ * @param iterations 반복 횟수 (기본: 100,000)
    30→ */
    31→export function hashPassword(
    32→  password: string,
    33→  saltBytes: number = 16,
    34→  iterations: number = 100000
    35→): PasswordHash {
    36→  const salt = crypto.randomBytes(saltBytes).toString("hex");
    37→
    38→  const hash = crypto
    39→    .pbkdf2Sync(password, salt, iterations, 32, "sha256")
    40→    .toString("hex");
    41→
    42→  return {
    43→    hash,
    44→    salt,
    45→    iterations,
    46→    algorithm: "PBKDF2-SHA256",
    47→  };
    48→}
    49→
    50→/**
    51→ * 비밀번호 검증
    52→ * @param password 입력된 평문 비밀번호
    53→ * @param storedHash 저장된 PasswordHash
    54→ */
    55→export function verifyPassword(password: string, storedHash: PasswordHash): boolean {
    56→  try {
    57→    const derivedHash = crypto
    58→      .pbkdf2Sync(password, storedHash.salt, storedHash.iterations, 32, "sha256")
    59→      .toString("hex");
    60→
    61→    // 상수-시간 비교로 타이밍 공격 방지
    62→    return crypto.timingSafeEqual(
    63→      Buffer.from(derivedHash),
    64→      Buffer.from(storedHash.hash)
    65→    );
    66→  } catch {
    67→    return false;
    68→  }
    69→}
    70→
    71→/**
    72→ * 비밀번호 강도 검증
    73→ * 요구사항:
    74→ * - 최소 8자
    75→ * - 대문자 1개 이상
    76→ * - 소문자 1개 이상
    77→ * - 숫자 1개 이상
    78→ * - 특수문자 1개 이상
    79→ */
    80→export function validatePasswordStrength(
    81→  password: string
    82→): { valid: boolean; strength: "weak" | "medium" | "strong"; issues: string[] } {
    83→  const issues: string[] = [];
    84→
    85→  if (password.length < 8) issues.push("최소 8자 필요");
    86→  if (!/[A-Z]/.test(password)) issues.push("대문자 1개 이상 필요");
    87→  if (!/[a-z]/.test(password)) issues.push("소문자 1개 이상 필요");
    88→  if (!/[0-9]/.test(password)) issues.push("숫자 1개 이상 필요");
    89→  if (!/[!@#$%^&*()_+\-=\[\]{};:'",.<>?/\\|`~]/.test(password)) {
    90→    issues.push("특수문자 1개 이상 필요");
    91→  }
    92→
    93→  // 강도 판정: 3개 이상 누락 = weak, 1-2개 누락 = medium, 0개 누락 = strong
    94→  const strength = issues.length === 0 ? "strong" : issues.length >= 3 ? "weak" : "medium";
    95→  return {
    96→    valid: issues.length === 0,
    97→    strength,
    98→    issues,
    99→  };
