  assert(Security.generateSecureToken !== undefined);
});

test("Security.sha256 — 함수 참조 확인", () => {
  assert(typeof Security.sha256 === "function");
  const result = Security.sha256("test");
  assert(result.length === 64, "SHA-256 출력은 64자여야 함");
});

test("Security.validateEmail — 함수 참조 확인", () => {
  assert(typeof Security.validateEmail === "function");
  assert(Security.validateEmail("test@example.com") === true);
  assert(Security.validateEmail("invalid-email") === false);
});

