// 5. Security Namespace (Phase 3.3 - 새 API)
// ============================================================
console.log("\n📋 5. Security Namespace (Phase 3.3)");

test("Security namespace 객체 존재 확인", () => {
  assert(typeof Security === "object", "Security는 object여야 함");
  // 주요 메서드 확인
  assert(Security.hashPassword !== undefined);
  assert(Security.verifyPassword !== undefined);
  assert(Security.validateEmail !== undefined);
  assert(Security.sha256 !== undefined);
  assert(Security.sanitizeHTML !== undefined);
  assert(Security.generateSecureToken !== undefined);
});

test("Security.sha256 — 함수 참조 확인", () => {
  assert(typeof Security.sha256 === "function");
  const result = Security.sha256("test");
  assert(result.length === 64, "SHA-256 출력은 64자여야 함");
});

test("Security.validateEmail — 함수 참조 확인", () => {
  assert(typeof Security.validateEmail === "function");
  assert(Security.validateEmail("test@example.com") === true);
  assert(Security.validateEmail("invalid-email") === false);
});

test("Security.sanitizeHTML — XSS 방지 확인", () => {
  assert(typeof Security.sanitizeHTML === "function");
  const xssInput = "<script>alert('XSS')</script>";
  const sanitized = Security.sanitizeHTML(xssInput);
  assert(!sanitized.includes("<script>"), "스크립트 태그 제거됨");
});

test("Security.generateSecureToken — 토큰 생성 확인", () => {
  assert(typeof Security.generateSecureToken === "function");
  const token = Security.generateSecureToken(32);
  assert(token.length === 64, "32바이트 토큰은 64자 hex여야 함"); // 32 bytes = 64 hex chars
});

// ============================================================
// 결과 출력
// ============================================================

const total = passed + failed;
console.log(`\n${"═".repeat(55)}`);
console.log(`  보안 테스트 결과: ${passed}/${total} 통과`);

