// 결과 출력
// ============================================================

const total = passed + failed;
console.log(`\n${"═".repeat(55)}`);
console.log(`  보안 테스트 결과: ${passed}/${total} 통과`);

if (failed > 0) {
  console.log(`\n  실패 목록:`);
  failures.forEach((f) => console.log(`    ✗ ${f}`));
  process.exit(1);
} else {
  console.log(`  모든 보안 테스트 통과! ✓`);
}

