/**
 * Unified HTTP System
 * Zero-copy HTTP pipeline with reactor pattern
 */

import { HTTPServer } from './server';
import { HTTPRouter } from './router';
import { HTTPResponseBuilder } from './response';
import { HTTPHeaders } from './headers';
import { QueryParser } from './query';
import {
  HTTPRequest,
  HTTPResponse,
  HTTPServerOptions,
  RouteHandler,
  ServerStatistics,
} from './types';

export class HTTPSystem {
  private server: HTTPServer;
  private router: HTTPRouter;
  private headers: HTTPHeaders;
  private queryParser: typeof QueryParser = QueryParser;

  constructor(options?: HTTPServerOptions) {
    this.server = new HTTPServer(options);
    this.router = new HTTPRouter();
    this.headers = new HTTPHeaders();
  }

  // ============== Server ==============

  /**
   * Serve HTTP server
   */
  async serve(): Promise<void> {
    return this.server.serve(async (req: HTTPRequest) => {
      try {
        // Match route
        const match = this.router.match(req);

        if (!match) {
          return new HTTPResponseBuilder()
            .status(404)
            .json({ error: 'Route not found' })
            .build();
        }

        // Add params to request
        req.params = match.params;

        // Execute handler
        const response = await match.handler(req, {
          statusCode: 200,
          headers: {},
        });

        return response;
      } catch (error) {
        return new HTTPResponseBuilder()
          .status(500)
          .json({ error: error instanceof Error ? error.message : 'Internal server error' })
          .build();
      }
    });
  }

  /**
   * Stop server
   */
  async stop(): Promise<void> {
    return this.server.stop();
  }

  /**
   * Check if server is running
   */
  isRunning(): boolean {
    return this.server.isServerRunning();
  }

  /**
   * Get server info
   */
  getServerInfo() {
    return this.server.getServerInfo();
  }

  // ============== Routing ==============

  /**
   * Register route
   */
  route(
    method: string | string[],
    pattern: string,
    handler: RouteHandler
  ): HTTPSystem {
    this.router.route(method, pattern, handler);
    return this;
  }

  /**
   * GET route
   */
  get(pattern: string, handler: RouteHandler): HTTPSystem {
    this.router.get(pattern, handler);
    return this;
  }

  /**
   * POST route
   */
  post(pattern: string, handler: RouteHandler): HTTPSystem {
    this.router.post(pattern, handler);
    return this;
  }

  /**
   * PUT route
   */
  put(pattern: string, handler: RouteHandler): HTTPSystem {
    this.router.put(pattern, handler);
    return this;
  }

  /**
   * DELETE route
   */
  delete(pattern: string, handler: RouteHandler): HTTPSystem {
    this.router.delete(pattern, handler);
    return this;
  }

  /**
   * PATCH route
   */
  patch(pattern: string, handler: RouteHandler): HTTPSystem {
    this.router.patch(pattern, handler);
    return this;
  }

  /**
   * List all routes
   */
  listRoutes() {
    return this.router.listRoutes();
  }

  /**
   * Get route count
   */
  getRouteCount(): number {
    return this.router.getRouteCount();
  }

  // ============== Response Builder ==============

  /**
   * Create response builder
   */
  response(): HTTPResponseBuilder {
    return new HTTPResponseBuilder();
  }

  /**
   * OK response
   */
  ok(data?: unknown): HTTPResponse {
    return this.response().ok(data);
  }

  /**
   * Created response
   */
  created(data?: unknown): HTTPResponse {
    return this.response().created(data);
  }

  /**
   * Bad request response
   */
  badRequest(message?: string): HTTPResponse {
    return this.response().badRequest(message);
  }

  /**
   * Unauthorized response
   */
  unauthorized(message?: string): HTTPResponse {
    return this.response().unauthorized(message);
  }

  /**
   * Forbidden response
   */
  forbidden(message?: string): HTTPResponse {
    return this.response().forbidden(message);
  }

  /**
   * Not found response
   */
  notFound(message?: string): HTTPResponse {
    return this.response().notFound(message);
  }

  /**
   * Internal error response
   */
  internalError(message?: string): HTTPResponse {
    return this.response().internalError(message);
  }

  // ============== Headers ==============

  /**
   * Create headers
   */
  createHeaders(): HTTPHeaders {
    return new HTTPHeaders();
  }

  /**
   * Set authorization header
   */
  setAuth(token: string, type: string = 'Bearer'): HTTPHeaders {
    return new HTTPHeaders().auth(type, token);
  }

  /**
   * Parse cookies
   */
  parseCookies(cookieString: string): Record<string, string> {
    return new HTTPHeaders().parseCookies(cookieString);
  }

  // ============== Query Parsing ==============

  /**
   * Parse query string
   */
  parseQuery(queryString: string) {
    return this.queryParser.parse(queryString);
  }

  /**
   * Parse query from URL
   */
  parseQueryFromURL(url: string) {
    return this.queryParser.parseFromURL(url);
  }

  /**
   * Build query string
   */
  buildQuery(query: Record<string, string | string[] | number | boolean>): string {
    return this.queryParser.build(query);
  }

  /**
   * Parse nested query
   */
  parseNestedQuery(queryString: string) {
    return this.queryParser.parseNested(queryString);
  }

  /**
   * Convert query to map
   */
  queryToMap(queryString: string): Map<string, string | string[]> {
    return this.queryParser.toMap(queryString);
  }

  /**
   * Validate query parameter
   */
  validateQueryParam(key: string, value: string) {
    return this.queryParser.validate(key, value);
  }

  /**
   * Get query statistics
   */
  getQueryStats(queryString: string) {
    return this.queryParser.getStats(queryString);
  }

  // ============== Statistics ==============

  /**
   * Get server statistics
   */
  getStatistics(): ServerStatistics {
    return this.server.getStatistics();
  }

  /**
   * Reset statistics
   */
  resetStatistics(): void {
    this.server.resetStatistics();
  }

  /**
   * Get performance report
   */
  getPerformanceReport() {
    const stats = this.server.getStatistics();

    return {
      requestsReceived: stats.requestsReceived,
      requestsProcessed: stats.requestsProcessed,
      requestsErrored: stats.requestsErrored,
      successRate:
        stats.requestsReceived > 0
          ? (
              ((stats.requestsProcessed / stats.requestsReceived) * 100).toFixed(2) + '%'
            )
          : '0%',
      averageResponseTime: `${stats.averageResponseTime.toFixed(2)}ms`,
      statusCodeDistribution: stats.statusCodeDistribution,
      methodDistribution: stats.methodDistribution,
      topPaths: Object.entries(stats.pathDistribution)
        .sort((a, b) => b[1] - a[1])
        .slice(0, 10),
      lastRequest: stats.lastRequest,
    };
  }
}

export default HTTPSystem;

